package com.collectionlogroulette;

import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import net.runelite.client.config.ConfigManager;
import org.mockito.invocation.InvocationOnMock;

import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * In-memory stand-in for RuneLite's RS-profile aware config storage.
 *
 * <p>Keys are namespaced by the active profile, which is what lets the tests
 * prove that two accounts cannot see each other's progress.
 */
public final class FakeConfigManager
{
	private final Map<String, String> store = new HashMap<>();

	@Nullable
	private String profileKey;

	private final ConfigManager mock;

	public FakeConfigManager(@Nullable String initialProfileKey)
	{
		this.profileKey = initialProfileKey;
		this.mock = mock(ConfigManager.class);

		when(this.mock.getRSProfileKey()).thenAnswer(invocation -> profileKey);

		when(this.mock.getRSProfileConfiguration(anyString(), anyString()))
			.thenAnswer(this::readProfileValue);

		doAnswer(this::writeProfileValue)
			.when(this.mock)
			.setRSProfileConfiguration(anyString(), anyString(), org.mockito.ArgumentMatchers.any());
	}

	public ConfigManager get()
	{
		return mock;
	}

	/** Simulates switching to a different RuneScape account. */
	public void setProfileKey(@Nullable String key)
	{
		this.profileKey = key;
	}

	@Nullable
	public String rawValue(String profile, String group, String key)
	{
		return store.get(profile + "|" + group + "|" + key);
	}

	/** Injects arbitrary text so corrupt-data handling can be exercised. */
	public void putRaw(String profile, String group, String key, String value)
	{
		store.put(profile + "|" + group + "|" + key, value);
	}

	@Nullable
	private Object readProfileValue(InvocationOnMock invocation)
	{
		if (profileKey == null)
		{
			return null;
		}

		return store.get(compositeKey(invocation.getArgument(0), invocation.getArgument(1)));
	}

	@Nullable
	private Object writeProfileValue(InvocationOnMock invocation)
	{
		if (profileKey == null)
		{
			// Mirrors the real manager, which has nowhere to write without a profile.
			return null;
		}

		final Object value = invocation.getArgument(2);
		store.put(compositeKey(invocation.getArgument(0), invocation.getArgument(1)),
			value == null ? null : value.toString());
		return null;
	}

	private String compositeKey(String group, String key)
	{
		return profileKey + "|" + group + "|" + key;
	}
}

package com.collectionlogroulette;

import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.CollectionLogTab;
import com.collectionlogroulette.model.DifficultyTier;
import com.collectionlogroulette.model.RouletteActivity;

/**
 * Small hand-made activities so selection and assignment tests do not depend on
 * the real catalog's contents (which change as activities are added).
 */
public final class TestActivities
{
	public static final int BOSS_ITEM_A = 1001;
	public static final int BOSS_ITEM_B = 1002;
	public static final int RAID_ITEM = 2001;
	public static final int CLUE_ITEM = 3001;

	/** Not present in any test activity — stands in for an unmapped item. */
	public static final int UNMAPPED_ITEM = 999_999;

	private TestActivities()
	{
	}

	public static RouletteActivity boss(String id)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(ActivityType.BOSS)
			.difficulty(DifficultyTier.MID)
			.tab(CollectionLogTab.BOSSES)
			.iconItemId(BOSS_ITEM_A)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.items(BOSS_ITEM_A, BOSS_ITEM_B)
			.npcs(50)
			.build();
	}

	public static RouletteActivity raid(String id)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(ActivityType.RAID)
			.difficulty(DifficultyTier.ELITE)
			.tab(CollectionLogTab.RAIDS)
			.iconItemId(RAID_ITEM)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.items(RAID_ITEM)
			.build();
	}

	public static RouletteActivity minigame(String id)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(ActivityType.MINIGAME)
			.difficulty(DifficultyTier.ENTRY)
			.tab(CollectionLogTab.MINIGAMES)
			.iconItemId(4001)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.items(4001)
			.build();
	}

	public static RouletteActivity clue(String id)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(ActivityType.CLUE)
			.difficulty(DifficultyTier.HIGH)
			.tab(CollectionLogTab.CLUES)
			.iconItemId(CLUE_ITEM)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.items(CLUE_ITEM)
			.build();
	}

	public static RouletteActivity other(String id)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(ActivityType.OTHER)
			.difficulty(DifficultyTier.ENTRY)
			.tab(CollectionLogTab.OTHER)
			.iconItemId(5001)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.items(5001)
			.build();
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.CollectionLogUnlock;
import java.util.Optional;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ChatCollectionLogDetectionServiceTest
{
	private ChatCollectionLogDetectionService service;

	@Before
	public void setUp()
	{
		service = new ChatCollectionLogDetectionService();
	}

	@Test
	public void parsesThePlainAnnouncement()
	{
		final Optional<CollectionLogUnlock> unlock =
			service.detectUnlock("New item added to your collection log: Verac's helm", 1_000L);

		assertTrue(unlock.isPresent());
		assertEquals("Verac's helm", unlock.get().getItemName());
		assertEquals(1_000L, unlock.get().getTimestampMillis());
		assertFalse("No id should be claimed at parse time", unlock.get().hasItemId());
	}

	@Test
	public void stripsColourTagsBeforeMatching()
	{
		final Optional<CollectionLogUnlock> unlock = service.detectUnlock(
			"<colNORMAL>New item added to your collection log: <col=ff0000>Twisted bow</col>", 1_000L);

		assertTrue(unlock.isPresent());
		assertEquals("Twisted bow", unlock.get().getItemName());
	}

	@Test
	public void stripsTrailingPunctuation()
	{
		assertEquals("Dragon warhammer", service
			.detectUnlock("New item added to your collection log: Dragon warhammer.", 1L)
			.orElseThrow(AssertionError::new)
			.getItemName());
	}

	@Test
	public void toleratesNonBreakingSpaces()
	{
		// The separator after the colon below is a real U+00A0, not a space — the
		// game emits those, and Java's \s and String.trim() both ignore them, so a
		// parser that does not fold them leaves the nbsp glued to the item name and
		// the subsequent item lookup silently fails. Do not "tidy" this literal.
		final String message = "New item added to your collection log: Bandos chestplate";

		assertEquals("Bandos chestplate", service
			.detectUnlock(message, 1L)
			.orElseThrow(AssertionError::new)
			.getItemName());
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertFalse(service.detectUnlock("You feel something weird sneaking into your backpack.", 1L).isPresent());
		assertFalse(service.detectUnlock("Your Barrows chest count is: 41.", 1L).isPresent());
		assertFalse(service.detectUnlock("", 1L).isPresent());
		assertFalse(service.detectUnlock(null, 1L).isPresent());
	}

	@Test
	public void ignoresPlayerChatQuotingTheAnnouncement()
	{
		// Anchoring at the start is what stops another player's message from
		// completing your assignment.
		assertFalse(service.detectUnlock(
			"Zezima: haha New item added to your collection log: Twisted bow", 1L).isPresent());
	}

	@Test
	public void suppressesDuplicateWithinTheWindow()
	{
		final long start = 10_000L;

		assertTrue(service.detectUnlock(
			"New item added to your collection log: Elysian sigil", start).isPresent());

		// The "both chat and popup" game setting delivers the same unlock twice.
		assertFalse("Duplicate inside the window must be suppressed",
			service.detectUnlock("New item added to your collection log: Elysian sigil", start + 200).isPresent());
	}

	@Test
	public void allowsTheSameItemAgainAfterTheWindow()
	{
		final long start = 10_000L;
		service.detectUnlock("New item added to your collection log: Bludgeon claw", start);

		assertTrue(service.detectUnlock("New item added to your collection log: Bludgeon claw",
			start + ChatCollectionLogDetectionService.DUPLICATE_WINDOW_MILLIS + 1).isPresent());
	}

	@Test
	public void differentItemsInQuickSuccessionAreBothReported()
	{
		final long start = 500L;

		assertTrue(service.detectUnlock("New item added to your collection log: Torva full helm", start).isPresent());
		assertTrue(service.detectUnlock("New item added to your collection log: Torva platebody", start + 50).isPresent());
	}

	@Test
	public void resetClearsDuplicateSuppression()
	{
		final long start = 1_000L;
		service.detectUnlock("New item added to your collection log: Zaryte vambraces", start);

		service.reset();

		assertTrue("After a reset the same item should be reportable again",
			service.detectUnlock("New item added to your collection log: Zaryte vambraces", start + 10).isPresent());
	}

	@Test
	public void parsesThePopUpNotificationVariant()
	{
		final Optional<CollectionLogUnlock> unlock =
			service.detectUnlockFromNotification("Collection log", "Abyssal whip", 2_000L);

		assertTrue(unlock.isPresent());
		assertEquals("Abyssal whip", unlock.get().getItemName());
	}

	@Test
	public void ignoresOtherPopUpNotifications()
	{
		assertFalse(service.detectUnlockFromNotification("Combat Achievements", "Hard tier complete", 1L).isPresent());
		assertFalse(service.detectUnlockFromNotification(null, "x", 1L).isPresent());
		assertFalse(service.detectUnlockFromNotification("Collection log", null, 1L).isPresent());
	}

	@Test
	public void chatAndPopUpForTheSameUnlockCountOnce()
	{
		final long start = 4_000L;

		assertTrue(service.detectUnlock(
			"New item added to your collection log: Kodai insignia", start).isPresent());

		assertFalse("The pop-up mirror of a chat announcement must not double-fire",
			service.detectUnlockFromNotification("Collection log", "Kodai insignia", start + 300).isPresent());
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.TestActivities;
import com.collectionlogroulette.model.RouletteActivity;
import com.collectionlogroulette.model.WeightCategory;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class AssignmentSelectionServiceTest
{
	private static Map<WeightCategory, Integer> defaultWeights()
	{
		final Map<WeightCategory, Integer> weights = new EnumMap<>(WeightCategory.class);
		weights.put(WeightCategory.BOSS_RAID, 40);
		weights.put(WeightCategory.MINIGAME, 35);
		weights.put(WeightCategory.CLUE, 20);
		weights.put(WeightCategory.OTHER, 5);
		return weights;
	}

	private static AssignmentSelectionService seeded(long seed)
	{
		return new AssignmentSelectionService(new Random(seed));
	}

	@Test
	public void emptyPoolYieldsNoSelection()
	{
		final Optional<RouletteActivity> result = seeded(1).select(
			Collections.emptyList(), null, SelectionMode.WEIGHTED, defaultWeights(), true);

		assertFalse("An empty eligible pool must not produce an assignment", result.isPresent());
	}

	@Test
	public void nullPoolYieldsNoSelection()
	{
		assertFalse(seeded(1)
			.select(null, null, SelectionMode.PURE_RANDOM, defaultWeights(), true)
			.isPresent());
	}

	@Test
	public void onlyEverSelectsFromTheSuppliedPool()
	{
		// "Disabled activities are never selected" is enforced by the caller
		// filtering them out; this asserts the service honours that contract and
		// never reaches outside the pool it was given.
		final List<RouletteActivity> pool = Arrays.asList(
			TestActivities.boss("enabled_a"), TestActivities.boss("enabled_b"));

		final AssignmentSelectionService service = seeded(12345);
		for (int i = 0; i < 500; i++)
		{
			final RouletteActivity chosen = service
				.select(pool, null, SelectionMode.WEIGHTED, defaultWeights(), false)
				.orElseThrow(AssertionError::new);

			assertTrue("Selected an activity outside the eligible pool: " + chosen.getId(),
				pool.contains(chosen));
		}
	}

	@Test
	public void avoidsImmediatelyPreviousActivityWhenAlternativesExist()
	{
		final List<RouletteActivity> pool = Arrays.asList(
			TestActivities.boss("alpha"), TestActivities.boss("beta"), TestActivities.boss("gamma"));

		final AssignmentSelectionService service = seeded(7);
		for (int i = 0; i < 300; i++)
		{
			final RouletteActivity chosen = service
				.select(pool, "alpha", SelectionMode.PURE_RANDOM, defaultWeights(), true)
				.orElseThrow(AssertionError::new);

			assertNotEquals("Rolled the immediately previous activity", "alpha", chosen.getId());
		}
	}

	@Test
	public void repeatsPreviousActivityWhenItIsTheOnlyOption()
	{
		// Refusing to roll would be worse than repeating; with one option left the
		// avoidance rule has to yield.
		final List<RouletteActivity> pool = Collections.singletonList(TestActivities.boss("solo"));

		final RouletteActivity chosen = seeded(3)
			.select(pool, "solo", SelectionMode.WEIGHTED, defaultWeights(), true)
			.orElseThrow(AssertionError::new);

		assertEquals("solo", chosen.getId());
	}

	@Test
	public void repeatAvoidanceCanBeTurnedOff()
	{
		final List<RouletteActivity> pool = Arrays.asList(
			TestActivities.boss("alpha"), TestActivities.boss("beta"));

		final AssignmentSelectionService service = seeded(99);
		boolean sawPrevious = false;
		for (int i = 0; i < 200 && !sawPrevious; i++)
		{
			sawPrevious = "alpha".equals(service
				.select(pool, "alpha", SelectionMode.PURE_RANDOM, defaultWeights(), false)
				.orElseThrow(AssertionError::new)
				.getId());
		}

		assertTrue("With avoidance off the previous activity should still be reachable", sawPrevious);
	}

	@Test
	public void weightedSelectionRespectsCategoryWeights()
	{
		// One activity per category keeps the within-category draw trivial, so the
		// observed distribution is purely the category weights.
		final List<RouletteActivity> pool = Arrays.asList(
			TestActivities.boss("boss"),
			TestActivities.minigame("minigame"),
			TestActivities.clue("clue"),
			TestActivities.other("other"));

		final AssignmentSelectionService service = seeded(2024);
		final Map<String, Integer> counts = new HashMap<>();

		final int runs = 40_000;
		for (int i = 0; i < runs; i++)
		{
			final RouletteActivity chosen = service
				.select(pool, null, SelectionMode.WEIGHTED, defaultWeights(), false)
				.orElseThrow(AssertionError::new);

			counts.merge(chosen.getId(), 1, Integer::sum);
		}

		assertWithinTolerance("boss", counts.get("boss") / (double) runs, 0.40);
		assertWithinTolerance("minigame", counts.get("minigame") / (double) runs, 0.35);
		assertWithinTolerance("clue", counts.get("clue") / (double) runs, 0.20);
		assertWithinTolerance("other", counts.get("other") / (double) runs, 0.05);
	}

	@Test
	public void weightOfZeroExcludesACategoryWhileOthersRemain()
	{
		final Map<WeightCategory, Integer> weights = defaultWeights();
		weights.put(WeightCategory.CLUE, 0);

		final List<RouletteActivity> pool = Arrays.asList(
			TestActivities.boss("boss"), TestActivities.clue("clue"));

		final AssignmentSelectionService service = seeded(5150);
		for (int i = 0; i < 2000; i++)
		{
			assertEquals("A zero-weighted category must not be drawn while others have weight",
				"boss",
				service.select(pool, null, SelectionMode.WEIGHTED, weights, false)
					.orElseThrow(AssertionError::new)
					.getId());
		}
	}

	@Test
	public void allZeroWeightsStillRollsSomething()
	{
		// A user can zero every weight; refusing to roll would look like a bug, so
		// the service falls back to a flat draw.
		final Map<WeightCategory, Integer> weights = new EnumMap<>(WeightCategory.class);
		for (WeightCategory category : WeightCategory.values())
		{
			weights.put(category, 0);
		}

		final List<RouletteActivity> pool = Arrays.asList(
			TestActivities.boss("boss"), TestActivities.clue("clue"));

		assertTrue(seeded(11)
			.select(pool, null, SelectionMode.WEIGHTED, weights, false)
			.isPresent());
	}

	@Test
	public void pureRandomCoversEveryActivity()
	{
		final List<RouletteActivity> pool = new ArrayList<>(Arrays.asList(
			TestActivities.boss("a"), TestActivities.raid("b"),
			TestActivities.minigame("c"), TestActivities.clue("d")));

		final AssignmentSelectionService service = seeded(808);
		final Map<String, Integer> counts = new HashMap<>();

		for (int i = 0; i < 8000; i++)
		{
			counts.merge(service.select(pool, null, SelectionMode.PURE_RANDOM, defaultWeights(), false)
				.orElseThrow(AssertionError::new)
				.getId(), 1, Integer::sum);
		}

		for (RouletteActivity activity : pool)
		{
			final double share = counts.getOrDefault(activity.getId(), 0) / 8000.0;
			assertWithinTolerance(activity.getId(), share, 0.25);
		}
	}

	/** Seeded RNG makes this deterministic; the tolerance absorbs normal variance. */
	private static void assertWithinTolerance(String label, double actual, double expected)
	{
		assertTrue(String.format("%s share was %.4f, expected around %.2f", label, actual, expected),
			Math.abs(actual - expected) < 0.02);
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.TestActivities;
import com.collectionlogroulette.TestConfig;
import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.CollectionLogTab;
import com.collectionlogroulette.model.DifficultyTier;
import com.collectionlogroulette.model.RouletteActivity;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ActivityEligibilityServiceTest
{
	private TestConfig config;
	private ActivityEligibilityService service;
	private List<RouletteActivity> catalog;

	@Before
	public void setUp()
	{
		config = new TestConfig();
		service = new ActivityEligibilityService(config);
		catalog = Arrays.asList(
			TestActivities.boss("boss"),
			TestActivities.raid("raid"),
			TestActivities.minigame("minigame"),
			TestActivities.clue("clue"),
			TestActivities.other("other"));
	}

	private Set<String> idsOf(List<RouletteActivity> activities)
	{
		return activities.stream().map(RouletteActivity::getId).collect(Collectors.toSet());
	}

	private List<RouletteActivity> filter(Function<RouletteActivity, CompletionState> completion)
	{
		return service.filterEligible(catalog, Collections.emptySet(), completion);
	}

	private static final Function<RouletteActivity, CompletionState> ALL_UNKNOWN =
		a -> CompletionState.UNKNOWN;

	private static final Function<RouletteActivity, CompletionState> ALL_INCOMPLETE =
		a -> CompletionState.INCOMPLETE;

	@Test
	public void everythingIsEligibleByDefault()
	{
		assertEquals(catalog.size(), filter(ALL_INCOMPLETE).size());
	}

	@Test
	public void disabledContentTypesAreExcluded()
	{
		config.enableBosses = false;
		config.enableClues = false;

		final Set<String> ids = idsOf(filter(ALL_INCOMPLETE));

		assertFalse(ids.contains("boss"));
		assertFalse(ids.contains("clue"));
		assertTrue(ids.contains("raid"));
		assertTrue(ids.contains("minigame"));
		assertTrue(ids.contains("other"));
	}

	@Test
	public void manuallyExcludedActivitiesAreRemoved()
	{
		final Set<String> excluded = new HashSet<>(Arrays.asList("raid", "other"));

		final Set<String> ids = idsOf(service.filterEligible(catalog, excluded, ALL_INCOMPLETE));

		assertFalse(ids.contains("raid"));
		assertFalse(ids.contains("other"));
		assertEquals(3, ids.size());
	}

	@Test
	public void difficultyRangeIsInclusive()
	{
		// minigame/other are ENTRY, boss is MID, clue is HIGH, raid is ELITE.
		config.minDifficulty = DifficultyTier.MID;
		config.maxDifficulty = DifficultyTier.HIGH;

		final Set<String> ids = idsOf(filter(ALL_INCOMPLETE));

		assertTrue(ids.contains("boss"));
		assertTrue(ids.contains("clue"));
		assertFalse(ids.contains("minigame"));
		assertFalse(ids.contains("raid"));
	}

	@Test
	public void invertedDifficultyRangeIsInterpretedCharitably()
	{
		// A user who sets min above max meant the range between them, not "nothing".
		config.minDifficulty = DifficultyTier.ELITE;
		config.maxDifficulty = DifficultyTier.MID;

		final Set<String> ids = idsOf(filter(ALL_INCOMPLETE));

		assertTrue(ids.contains("boss"));
		assertTrue(ids.contains("clue"));
		assertTrue(ids.contains("raid"));
		assertFalse(ids.contains("minigame"));
	}

	@Test
	public void completedPagesAreNeverEligible()
	{
		final Function<RouletteActivity, CompletionState> completed =
			a -> "boss".equals(a.getId()) ? CompletionState.COMPLETE : CompletionState.INCOMPLETE;

		assertFalse("A fully collected page has nothing left to win",
			idsOf(filter(completed)).contains("boss"));
	}

	@Test
	public void unknownStateIsAllowedByDefault()
	{
		assertEquals(catalog.size(), filter(ALL_UNKNOWN).size());
	}

	@Test
	public void unknownStateCanBeRequiredToBeKnown()
	{
		config.allowUnknownCompletion = false;

		assertTrue("With unknown state disallowed nothing should be rollable",
			filter(ALL_UNKNOWN).isEmpty());
	}

	@Test
	public void activitiesWithPrerequisitesCanBeFilteredOut()
	{
		final RouletteActivity gated = RouletteActivity.builder()
			.id("gated")
			.displayName("Gated")
			.type(ActivityType.BOSS)
			.difficulty(DifficultyTier.MID)
			.tab(CollectionLogTab.BOSSES)
			.iconItemId(1)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.prerequisiteNote("Requires a quest.")
			.items(1)
			.build();

		final List<RouletteActivity> withGated = Arrays.asList(TestActivities.boss("boss"), gated);

		config.includeUnmetPrerequisites = false;
		final Set<String> ids = idsOf(
			service.filterEligible(withGated, Collections.emptySet(), ALL_INCOMPLETE));

		assertFalse(ids.contains("gated"));
		assertTrue(ids.contains("boss"));
	}

	@Test
	public void allFiltersCombine()
	{
		config.enableRaids = false;
		config.minDifficulty = DifficultyTier.ENTRY;
		config.maxDifficulty = DifficultyTier.MID;

		final Set<String> excluded = Collections.singleton("other");
		final Function<RouletteActivity, CompletionState> completion =
			a -> "minigame".equals(a.getId()) ? CompletionState.COMPLETE : CompletionState.INCOMPLETE;

		final Set<String> ids = idsOf(service.filterEligible(catalog, excluded, completion));

		assertEquals(Collections.singleton("boss"), ids);
	}
}

package com.collectionlogroulette.service;

