public class AssignmentServiceTest
{
	private static final String BOSS = "test_boss";
	private static final String RAID = "test_raid";

	private TestConfig config;
	private AssignmentService service;
	private AtomicLong clock;
	private FakeConfigManager configManager;

	@Before
	public void setUp()
	{
		clock = new AtomicLong(1_000_000L);
		config = new TestConfig();
		configManager = new FakeConfigManager("profile-a");

		service = buildService(config, configManager, clock);
		service.loadForCurrentProfile();
	}

	private static AssignmentService buildService(TestConfig config, FakeConfigManager configManager,
		AtomicLong clock)
	{
		final List<RouletteActivity> activities = Arrays.asList(
			TestActivities.boss(BOSS), TestActivities.raid(RAID));

		final ActivityCatalog catalog = new ActivityCatalog(activities);

		return new AssignmentService(
			catalog,
			new AssignmentSelectionService(new Random(42)),
			new ActivityEligibilityService(config),
			new PersistenceService(configManager.get(), new Gson()),
			config,
			clock::get);
	}

	/** Forces a specific assignment regardless of what the RNG would pick. */
	private void assign(String activityId)
	{
		service.getData().setCurrentAssignment(new Assignment(activityId, clock.get()));
	}

	// ------------------------------------------------------------------
	// Rolling
	// ------------------------------------------------------------------

	@Test
	public void rollProducesAnActiveAssignment()
	{
		final RollResult result = service.roll();

		assertTrue(result.isRolled());
		assertNotNull(result.getActivity());
		assertEquals(AssignmentState.ACTIVE, service.getState());
	}

	@Test
	public void rollIsRefusedWhileAnAssignmentIsActive()
	{
		service.roll();
		final String firstId = service.getCurrentAssignment().getActivityId();

		final RollResult second = service.roll();

		assertFalse("Rolling over an active assignment must be refused", second.isRolled());
		assertEquals(RollResult.Status.BLOCKED_ACTIVE, second.getStatus());
		assertEquals("The active assignment must be untouched",
			firstId, service.getCurrentAssignment().getActivityId());
	}

	@Test
	public void rollIsAllowedAfterCompletion()
	{
		assign(BOSS);
		service.completeManually("Whatever", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		assertEquals(AssignmentState.COMPLETED, service.getState());

		assertTrue("Rolling over a completed assignment is fine", service.roll().isRolled());
		assertEquals(AssignmentState.ACTIVE, service.getState());
	}

	@Test
	public void rollIsRefusedWithNoAccountLoggedIn()
	{
		// Without a profile the roll could not be saved, so it would silently
		// vanish the moment an account logged in.
		configManager.setProfileKey(null);
		service.loadForCurrentProfile();

		final RollResult result = service.roll();

		assertFalse(result.isRolled());
		assertEquals(RollResult.Status.NO_PROFILE, result.getStatus());
		assertEquals(AssignmentState.NONE, service.getState());
		assertNull(service.getCurrentAssignment());
	}

	@Test
	public void rollWorksAgainOnceAnAccountIsLoggedIn()
	{
		configManager.setProfileKey(null);
		service.loadForCurrentProfile();
		assertFalse(service.roll().isRolled());

		configManager.setProfileKey("profile-a");
		service.loadForCurrentProfile();

		assertTrue(service.roll().isRolled());
		assertEquals(AssignmentState.ACTIVE, service.getState());
	}

	@Test
	public void rollReportsWhenNothingIsEligible()
	{
		config.enableBosses = false;
		config.enableRaids = false;

		final RollResult result = service.roll();

		assertFalse(result.isRolled());
		assertEquals(RollResult.Status.NO_ELIGIBLE_ACTIVITIES, result.getStatus());
		assertEquals(AssignmentState.NONE, service.getState());
	}

	@Test
	public void activitiesDisabledByDefaultStartExcludedButStayUserControlled()
	{
		final ActivityCatalog optInCatalog = new ActivityCatalog(
			Arrays.asList(TestActivities.boss(BOSS), optOutRaid()));

		final AssignmentService first = serviceOver(optInCatalog);
		first.loadForCurrentProfile();

		assertTrue("An activity that is not enabled by default should start excluded",
			first.isExcluded(RAID));

		// The player turns it on; a later load must not undo that.
		first.setExcluded(RAID, false);
		first.save();

		final AssignmentService reloaded = serviceOver(optInCatalog);
		reloaded.loadForCurrentProfile();

		assertFalse("Defaults must be applied once, not re-imposed on every load",
			reloaded.isExcluded(RAID));
	}

	private AssignmentService serviceOver(ActivityCatalog catalog)
	{
		return new AssignmentService(
			catalog,
			new AssignmentSelectionService(new Random(1)),
			new ActivityEligibilityService(config),
			new PersistenceService(configManager.get(), new Gson()),
			config,
			clock::get);
	}

	private static RouletteActivity optOutRaid()
	{
		return RouletteActivity.builder()
			.id(RAID)
			.displayName(RAID)
			.type(ActivityType.RAID)
			.difficulty(DifficultyTier.ELITE)
			.tab(CollectionLogTab.RAIDS)
			.iconItemId(TestActivities.RAID_ITEM)
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(false)
			.items(TestActivities.RAID_ITEM)
			.build();
	}

	@Test
	public void excludedActivitiesAreNeverRolled()
	{
		service.setExcluded(RAID, true);

		for (int i = 0; i < 50; i++)
		{
			service.roll();
			assertEquals("An excluded activity was rolled", BOSS, service.getCurrentAssignment().getActivityId());
			service.resetCurrent();
		}
	}

	// ------------------------------------------------------------------
	// Unlock handling
