	@Test
	public void matchingItemCompletesTheAssignment()
	{
		assign(BOSS);

		final UnlockOutcome outcome = service.offerUnlock(
			new CollectionLogUnlock("Item A", TestActivities.BOSS_ITEM_A, clock.get()));

		assertEquals(UnlockOutcome.COMPLETED, outcome);
		assertEquals(AssignmentState.COMPLETED, service.getState());
		assertEquals(VerificationMethod.AUTOMATIC, service.getCurrentAssignment().getVerification());
		assertEquals(1, service.getData().getCompletedCount());
		assertEquals(1, service.getData().getUnlocksEarned());
	}

	@Test
	public void unrelatedMappedItemDoesNotCompleteTheAssignment()
	{
		assign(BOSS);

		// RAID_ITEM belongs to a different catalog activity, so this is knowably
		// unrelated rather than merely unrecognised.
		final UnlockOutcome outcome = service.offerUnlock(
			new CollectionLogUnlock("Raid item", TestActivities.RAID_ITEM, clock.get()));

		assertEquals(UnlockOutcome.UNRELATED, outcome);
		assertEquals(AssignmentState.ACTIVE, service.getState());
		assertEquals(0, service.getData().getCompletedCount());
		assertNull("An unrelated item must not raise a confirmation prompt",
			service.getCurrentAssignment().getPendingUnlock());
	}

	@Test
	public void unmappableItemAsksForConfirmationInsteadOfGuessing()
	{
		assign(BOSS);

		final UnlockOutcome outcome = service.offerUnlock(
			new CollectionLogUnlock("Mystery item", TestActivities.UNMAPPED_ITEM, clock.get()));

		assertEquals(UnlockOutcome.NEEDS_CONFIRMATION, outcome);
		assertEquals("The assignment must stay active until the player answers",
			AssignmentState.ACTIVE, service.getState());
		assertNotNull(service.getCurrentAssignment().getPendingUnlock());
		assertEquals(0, service.getData().getCompletedCount());
	}

	@Test
	public void unresolvedItemNameAsksForConfirmation()
	{
		assign(BOSS);

		final UnlockOutcome outcome = service.offerUnlock(
			new CollectionLogUnlock("Some item the plugin could not resolve", clock.get()));

		assertEquals(UnlockOutcome.NEEDS_CONFIRMATION, outcome);
		assertEquals(AssignmentState.ACTIVE, service.getState());
	}

	@Test
	public void confirmingAPendingUnlockCompletesItAsManual()
	{
		assign(BOSS);
		service.offerUnlock(new CollectionLogUnlock("Mystery", TestActivities.UNMAPPED_ITEM, clock.get()));

		assertTrue(service.confirmPendingUnlock());

		assertEquals(AssignmentState.COMPLETED, service.getState());
		assertEquals("A player-confirmed unlock is not something the plugin verified",
			VerificationMethod.MANUAL, service.getCurrentAssignment().getVerification());
	}

	@Test
	public void dismissingAPendingUnlockKeepsTheAssignmentRunning()
	{
		assign(BOSS);
		service.offerUnlock(new CollectionLogUnlock("Mystery", TestActivities.UNMAPPED_ITEM, clock.get()));

		service.dismissPendingUnlock();

		assertNull(service.getCurrentAssignment().getPendingUnlock());
		assertEquals(AssignmentState.ACTIVE, service.getState());
		assertEquals(0, service.getData().getCompletedCount());
	}

	@Test
	public void duplicateUnlockEventsDoNotCompleteTwice()
	{
		assign(BOSS);

		final CollectionLogUnlock unlock =
			new CollectionLogUnlock("Item A", TestActivities.BOSS_ITEM_A, clock.get());

		assertEquals(UnlockOutcome.COMPLETED, service.offerUnlock(unlock));
		// A second delivery of the same event must not double-count.
		assertEquals(UnlockOutcome.IGNORED, service.offerUnlock(unlock));
		assertEquals(UnlockOutcome.IGNORED, service.offerUnlock(
			new CollectionLogUnlock("Item B", TestActivities.BOSS_ITEM_B, clock.get())));

		assertEquals(1, service.getData().getCompletedCount());
		assertEquals(1, service.getData().getUnlocksEarned());
		assertEquals(1, service.getData().getCurrentStreak());
		assertEquals(1, service.getHistory().size());
	}

	@Test
	public void unlocksWithNoActiveAssignmentAreStillCached()
	{
		// The local cache of observed unlocks is part of the eligibility fallback
		// hierarchy, so it should fill in even when nothing is assigned.
		service.offerUnlock(new CollectionLogUnlock("Item A", TestActivities.BOSS_ITEM_A, clock.get()));

		assertTrue(service.getData().getObservedUnlockItemIds().contains(TestActivities.BOSS_ITEM_A));
		assertEquals(0, service.getData().getCompletedCount());
	}

