	@Test
	public void playerStartsWithNoSkips()
	{
		assertEquals(0, service.getData().getAvailableSkips());
		assertFalse(service.canSkip());
	}

	@Test
	public void skipIsRefusedWithoutABankedSkip()
	{
		assign(BOSS);

		final SkipResult result = service.skip(SkipReason.PERSONAL_CHOICE);

		assertFalse(result.isSkipped());
		assertEquals(SkipResult.Status.NO_SKIPS_AVAILABLE, result.getStatus());
		assertEquals(AssignmentState.ACTIVE, service.getState());
	}

	@Test
	public void oneSkipIsEarnedEveryNCompletions()
	{
		config.completionsPerSkip = 3;

		for (int i = 0; i < 2; i++)
		{
			assign(BOSS);
			service.completeManually("x", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		}
		assertEquals("No skip yet at 2 of 3 completions", 0, service.getData().getAvailableSkips());

		assign(BOSS);
		service.completeManually("x", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		assertEquals(1, service.getData().getAvailableSkips());

		for (int i = 0; i < 3; i++)
		{
			assign(BOSS);
			service.completeManually("x", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		}
		assertEquals(2, service.getData().getAvailableSkips());
	}

	@Test
	public void skippingConsumesASkipAndDoesNotCountAsACompletion()
	{
		config.completionsPerSkip = 1;

		assign(BOSS);
		service.completeManually("x", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		assertEquals(1, service.getData().getAvailableSkips());

		assign(RAID);
		final SkipResult result = service.skip(SkipReason.TOO_DIFFICULT);

		assertTrue(result.isSkipped());
		assertEquals(0, service.getData().getAvailableSkips());
		assertEquals(1, service.getData().getTotalSkipped());
		assertEquals("A skip must not count as a completion", 1, service.getData().getCompletedCount());
		assertEquals("A skip must not award a log slot", 1, service.getData().getUnlocksEarned());
		assertEquals(AssignmentState.NONE, service.getState());

		final AssignmentHistoryEntry entry = service.getHistory().get(0);
		assertEquals(AssignmentResult.SKIPPED, entry.getResult());
		assertEquals(SkipReason.TOO_DIFFICULT, entry.getSkipReason());
	}

	@Test
	public void unlimitedSkipModeNeedsNoBankedSkips()
	{
		config.skipMode = SkipMode.UNLIMITED;
		assign(BOSS);

		assertTrue(service.canSkip());
		assertTrue(service.skip(SkipReason.PERSONAL_CHOICE).isSkipped());
		assertEquals("Unlimited mode must not decrement the counter",
			0, service.getData().getAvailableSkips());
	}

	@Test
	public void skipsDisabledModeRefusesEverything()
	{
		config.skipMode = SkipMode.NONE;
		service.getData().setAvailableSkips(5);
		assign(BOSS);

		assertFalse(service.canSkip());
		assertEquals(SkipResult.Status.SKIPS_DISABLED, service.skip(null).getStatus());
		assertEquals(AssignmentState.ACTIVE, service.getState());
	}

	@Test
	public void skippingWithNothingActiveIsReported()
	{
		config.skipMode = SkipMode.UNLIMITED;
		assertEquals(SkipResult.Status.NO_ACTIVE_ASSIGNMENT, service.skip(null).getStatus());
	}

