	@Test
	public void progressSurvivesAReload()
	{
		config.skipMode = SkipMode.UNLIMITED;

		assign(BOSS);
		clock.addAndGet(20_000L);
		service.recordLoot(TestActivities.BOSS_ITEM_A, 1, 1234, "Test boss");
		service.recordKill();
		service.completeManually("Persisted item", CollectionLogUnlock.UNKNOWN_ITEM_ID);

		assign(RAID);
		clock.addAndGet(7_000L);
		service.pauseTimer();

		// A fresh service over the same storage stands in for a client restart.
		final AssignmentService reloaded = buildService(config, configManager, clock);
		reloaded.loadForCurrentProfile();

		assertEquals(1, reloaded.getData().getCompletedCount());
		assertEquals(1, reloaded.getData().getCurrentStreak());
		assertEquals(1, reloaded.getHistory().size());
		assertEquals("Persisted item", reloaded.getHistory().get(0).getUnlockItemName());
		assertEquals(1234L, reloaded.getHistory().get(0).getEstimatedLootValue());

		assertNotNull(reloaded.getCurrentAssignment());
		assertEquals(RAID, reloaded.getCurrentAssignment().getActivityId());
		assertEquals(AssignmentState.ACTIVE, reloaded.getState());
		assertEquals("Banked time must survive the restart", 7_000L, reloaded.getElapsedMillis());
	}

	@Test
	public void timeDoesNotAccrueWhileTheClientIsClosed()
	{
		assign(BOSS);
		clock.addAndGet(10_000L);
		service.pauseTimer();

		// Simulate hours passing with RuneLite shut down.
		clock.addAndGet(6 * 60 * 60 * 1000L);

		final AssignmentService reloaded = buildService(config, configManager, clock);
		reloaded.loadForCurrentProfile();

		assertEquals(10_000L, reloaded.getElapsedMillis());
	}

	@Test
	public void uncleanShutdownKeepsCheckpointedTimeAndNothingMore()
	{
		// The autosave checkpointed the clock, then the client died without ever
		// pausing. The hour that follows is not playtime and must not be credited.
		assign(BOSS);
		clock.addAndGet(10_000L);
		service.save();

		clock.addAndGet(60 * 60 * 1000L);

		final AssignmentService reloaded = buildService(config, configManager, clock);
		reloaded.loadForCurrentProfile();

		assertFalse("A restored assignment must start paused",
			reloaded.getCurrentAssignment().isTimerRunning());
		assertEquals("Only the checkpointed time should survive an unclean exit",
			10_000L, reloaded.getElapsedMillis());
	}

	@Test
	public void savingRepeatedlyDoesNotInflateElapsedTime()
	{
		// Checkpointing banks and reopens the interval; doing it often must stay
		// equivalent to one long interval.
		assign(BOSS);

		for (int i = 0; i < 10; i++)
		{
			clock.addAndGet(1_000L);
			service.save();
		}

		assertEquals(10_000L, service.getElapsedMillis());
	}

	@Test
	public void assignmentForAnActivityThisBuildNoLongerHasIsDiscarded()
	{
		// A save written by a version whose catalog had an activity this build has
		// dropped or renamed. Keeping it would leave the state ACTIVE — blocking
		// Roll — while the panel had no definition to render, so no Skip or Reset
		// button would be reachable either.
		assign(BOSS);
		service.save();

		final ActivityCatalog withoutBoss = new ActivityCatalog(
			Collections.singletonList(TestActivities.raid(RAID)));

		final AssignmentService reloaded = serviceOver(withoutBoss);
		reloaded.loadForCurrentProfile();

		assertNull("A dangling assignment must be dropped, not left blocking",
			reloaded.getCurrentAssignment());
		assertEquals(AssignmentState.NONE, reloaded.getState());
		assertTrue("Dropping the assignment must not block rolling", reloaded.roll().isRolled());
	}

	@Test
	public void discardingADanglingAssignmentKeepsCountersAndHistory()
	{
		service.getData().setCompletedCount(7);
		service.getData().setCurrentStreak(3);
		assign(BOSS);
		service.completeManually("Kept item", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		assign(BOSS);
		service.save();

		final AssignmentService reloaded = serviceOver(
			new ActivityCatalog(Collections.singletonList(TestActivities.raid(RAID))));
		reloaded.loadForCurrentProfile();

		assertNull(reloaded.getCurrentAssignment());
		assertEquals("Counters are unrelated to the dangling activity",
			8, reloaded.getData().getCompletedCount());
		assertFalse(reloaded.getHistory().isEmpty());
		assertEquals("Kept item", reloaded.getHistory().get(0).getUnlockItemName());
	}

	@Test
	public void accountsDoNotShareProgress()
	{
		assign(BOSS);
		service.completeManually("Account A item", CollectionLogUnlock.UNKNOWN_ITEM_ID);
		service.setExcluded(RAID, true);

		configManager.setProfileKey("profile-b");
		service.loadForCurrentProfile();

		assertEquals("A second account must start clean", 0, service.getData().getCompletedCount());
		assertTrue(service.getHistory().isEmpty());
		assertNull(service.getCurrentAssignment());
		assertFalse(service.isExcluded(RAID));

		assign(RAID);
		service.completeManually("Account B item", CollectionLogUnlock.UNKNOWN_ITEM_ID);

		configManager.setProfileKey("profile-a");
		service.loadForCurrentProfile();

		assertEquals(1, service.getData().getCompletedCount());
		assertEquals("Account A's history must be intact",
			"Account A item", service.getHistory().get(0).getUnlockItemName());
		assertTrue(service.isExcluded(RAID));
	}

	@Test
	public void progressIsNotWrittenWithoutAnActiveProfile()
	{
		configManager.setProfileKey(null);
		service.loadForCurrentProfile();

		assign(BOSS);
		service.completeManually("Nowhere item", CollectionLogUnlock.UNKNOWN_ITEM_ID);

		configManager.setProfileKey("profile-a");
		service.loadForCurrentProfile();

		assertEquals("Logged-out progress must not leak into a real account",
			0, service.getData().getCompletedCount());
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.FakeConfigManager;
import com.collectionlogroulette.TestActivities;
import com.collectionlogroulette.TestConfig;
import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.Assignment;
import com.collectionlogroulette.model.CollectionLogTab;
import com.collectionlogroulette.model.CollectionLogUnlock;
import com.collectionlogroulette.model.DifficultyTier;
import com.collectionlogroulette.model.RouletteActivity;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Random;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class KillTrackingServiceTest
{
	private static final int BOSS_NPC = 50;

	/** Stands in for Dagannoth Kings: several NPCs, one assignment. */
	private static final RouletteActivity MULTI_NPC = RouletteActivity.builder()
		.id("multi")
		.displayName("Multi")
		.type(ActivityType.BOSS)
		.difficulty(DifficultyTier.MID)
		.tab(CollectionLogTab.BOSSES)
		.iconItemId(1)
		.completionVarbitId(RouletteActivity.NO_VARBIT)
		.enabledByDefault(true)
		.items(1)
		.npcs(101, 102, 103)
		.build();

	private AssignmentService assignmentService;
	private KillTrackingService killTracking;
	private AtomicLong clock;

	@Before
	public void setUp()
	{
		clock = new AtomicLong(1_000L);
		final TestConfig config = new TestConfig();

		final ActivityCatalog catalog = new ActivityCatalog(Arrays.asList(
			TestActivities.boss("boss"), TestActivities.clue("clue"), MULTI_NPC));

		assignmentService = new AssignmentService(
			catalog,
			new AssignmentSelectionService(new Random(1)),
			new ActivityEligibilityService(config),
			new PersistenceService(new FakeConfigManager("p").get(), new Gson()),
			config,
			clock::get);

		assignmentService.loadForCurrentProfile();
		killTracking = new KillTrackingService(assignmentService);
	}

	private void assign(String id)
	{
		assignmentService.getData().setCurrentAssignment(new Assignment(id, clock.get()));
	}

	@Test
	public void countsKillsOfTheAssignedNpc()
	{
		assign("boss");

		assertTrue(killTracking.onNpcKilled(BOSS_NPC, 1));
		assertTrue(killTracking.onNpcKilled(BOSS_NPC, 2));

		assertEquals(2, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void ignoresNpcsThatDoNotBelongToTheAssignment()
	{
		assign("boss");

		assertFalse(killTracking.onNpcKilled(9999, 1));
		assertEquals(0, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void countsEveryNpcOfAMultiNpcActivity()
	{
		// Dagannoth Kings style: three different NPCs, all the same assignment.
		assign("multi");

		assertTrue(killTracking.onNpcKilled(101, 1));
		assertTrue(killTracking.onNpcKilled(102, 2));
		assertTrue(killTracking.onNpcKilled(103, 3));

		assertEquals(3, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void suppressesTheSameKillReportedTwiceOnOneTick()
	{
		// RuneLite can surface one death through more than one loot event.
		assign("boss");

		assertTrue(killTracking.onNpcKilled(BOSS_NPC, 7));
		assertFalse("The same npc on the same tick is one kill",
			killTracking.onNpcKilled(BOSS_NPC, 7));

		assertEquals(1, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void theSameNpcOnALaterTickIsANewKill()
	{
		assign("boss");

		killTracking.onNpcKilled(BOSS_NPC, 7);
		assertTrue(killTracking.onNpcKilled(BOSS_NPC, 8));

		assertEquals(2, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void activitiesWithoutNpcsNeverCount()
	{
		// Clues have no reliable per-completion signal, so nothing is invented.
		assign("clue");

		assertFalse(killTracking.onNpcKilled(BOSS_NPC, 1));
		assertEquals(0, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void nothingIsCountedWithoutAnAssignment()
	{
		assertFalse(killTracking.onNpcKilled(BOSS_NPC, 1));
	}

	@Test
	public void killsStopCountingOnceCompleted()
	{
		assign("boss");
		killTracking.onNpcKilled(BOSS_NPC, 1);
		assignmentService.completeManually("x", CollectionLogUnlock.UNKNOWN_ITEM_ID);

		assertFalse(killTracking.onNpcKilled(BOSS_NPC, 2));
		assertEquals(1, assignmentService.getCurrentAssignment().getKillCount());
	}

	@Test
	public void resetClearsDuplicateSuppression()
	{
		assign("boss");
		killTracking.onNpcKilled(BOSS_NPC, 7);

		killTracking.reset();

		assertTrue(killTracking.onNpcKilled(BOSS_NPC, 7));
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.CollectionLogRouletteConfig;
import com.collectionlogroulette.FakeConfigManager;
import com.collectionlogroulette.model.Assignment;
import com.collectionlogroulette.model.AssignmentHistoryEntry;
import com.collectionlogroulette.model.AssignmentResult;
import com.collectionlogroulette.model.AssignmentState;
import com.collectionlogroulette.model.RouletteSaveData;
import com.collectionlogroulette.model.VerificationMethod;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class PersistenceServiceTest
{
	private FakeConfigManager configManager;
	private PersistenceService service;

	@Before
	public void setUp()
	{
		configManager = new FakeConfigManager("profile-a");
		service = new PersistenceService(configManager.get(), new Gson());
	}

	@Test
	public void loadingWithNothingStoredGivesEmptyData()
	{
		final RouletteSaveData data = service.load();

		assertNotNull(data);
		assertEquals(RouletteSaveData.CURRENT_SCHEMA_VERSION, data.getSchemaVersion());
		assertEquals(0, data.getCompletedCount());
		assertNull(data.getCurrentAssignment());
		assertTrue(data.getHistory().isEmpty());
	}

	@Test
	public void roundTripsEveryPersistedField()
	{
		final RouletteSaveData data = new RouletteSaveData();
		data.setCompletedCount(12);
		data.setCurrentStreak(4);
		data.setBestStreak(9);
		data.setAvailableSkips(2);
		data.setTotalSkipped(3);
		data.setUnlocksEarned(12);
		data.setCompletionsTowardsNextSkip(7);
		data.setPreviousActivityId("barrows");
		data.getExcludedActivityIds().add("zulrah");
		data.getObservedUnlockItemIds().add(4708);

		final Assignment assignment = new Assignment("vorkath", 5_000L);
		assignment.setKillCount(41);
		assignment.setAccumulatedMillis(123_456L);
		data.setCurrentAssignment(assignment);

		data.addHistoryEntry(AssignmentHistoryEntry.builder()
			.activityId("barrows")
			.activityName("Barrows")
			.startTimeMillis(1_000L)
			.endTimeMillis(2_000L)
			.durationMillis(1_000L)
			.result(AssignmentResult.COMPLETED)
			.unlockItemId(4753)
			.unlockItemName("Verac's helm")
			.estimatedLootValue(3_400_000L)
			.killCount(41)
			.verification(VerificationMethod.AUTOMATIC)
			.build());

		service.save(data);
		final RouletteSaveData restored = service.load();

		assertEquals(12, restored.getCompletedCount());
		assertEquals(4, restored.getCurrentStreak());
		assertEquals(9, restored.getBestStreak());
		assertEquals(2, restored.getAvailableSkips());
		assertEquals(3, restored.getTotalSkipped());
		assertEquals(12, restored.getUnlocksEarned());
		assertEquals(7, restored.getCompletionsTowardsNextSkip());
		assertEquals("barrows", restored.getPreviousActivityId());
		assertTrue(restored.getExcludedActivityIds().contains("zulrah"));
		assertTrue(restored.getObservedUnlockItemIds().contains(4708));

		assertNotNull(restored.getCurrentAssignment());
		assertEquals("vorkath", restored.getCurrentAssignment().getActivityId());
		assertEquals(AssignmentState.ACTIVE, restored.getCurrentAssignment().getState());
		assertEquals(41, restored.getCurrentAssignment().getKillCount());
		assertEquals(123_456L, restored.getCurrentAssignment().getAccumulatedMillis());

		assertEquals(1, restored.getHistory().size());
		final AssignmentHistoryEntry entry = restored.getHistory().get(0);
		assertEquals("Barrows", entry.getActivityName());
		assertEquals(AssignmentResult.COMPLETED, entry.getResult());
		assertEquals(VerificationMethod.AUTOMATIC, entry.getVerification());
		assertEquals("Verac's helm", entry.getUnlockItemName());
		assertEquals(3_400_000L, entry.getEstimatedLootValue());
	}

	@Test
	public void malformedJsonFallsBackToEmptyDataInsteadOfThrowing()
	{
		configManager.putRaw("profile-a", CollectionLogRouletteConfig.GROUP,
			PersistenceService.KEY_SAVE_DATA, "{ this is not json ");

		final RouletteSaveData data = service.load();

		assertNotNull("Corrupt data must never take the client down", data);
		assertEquals(0, data.getCompletedCount());
		assertTrue(data.getHistory().isEmpty());
	}

	@Test
	public void truncatedJsonFallsBackToEmptyData()
	{
		configManager.putRaw("profile-a", CollectionLogRouletteConfig.GROUP,
			PersistenceService.KEY_SAVE_DATA, "{\"schemaVersion\":1,\"completedCount\":");

		assertEquals(0, service.load().getCompletedCount());
	}

	@Test
	public void unknownEnumValuesFallBackToEmptyData()
	{
		// A save written by a future build could name a result this build has
		// never heard of.
		configManager.putRaw("profile-a", CollectionLogRouletteConfig.GROUP,
			PersistenceService.KEY_SAVE_DATA,
			"{\"schemaVersion\":1,\"completedCount\":5,\"history\":[{\"result\":\"TELEPORTED\"}]}");

		final RouletteSaveData data = service.load();
		assertNotNull(data);
		// Gson maps unknown enum constants to null rather than throwing, so the
		// blob still loads; what matters is that nothing blew up.
		assertTrue(data.getHistory().isEmpty() || data.getHistory().get(0).getResult() == null);
	}

	@Test
	public void emptyStringIsTreatedAsNoSave()
	{
		configManager.putRaw("profile-a", CollectionLogRouletteConfig.GROUP,
			PersistenceService.KEY_SAVE_DATA, "   ");

		assertEquals(0, service.load().getCompletedCount());
	}

	@Test
	public void newerSchemaVersionsAreNotMisread()
	{
		configManager.putRaw("profile-a", CollectionLogRouletteConfig.GROUP,
			PersistenceService.KEY_SAVE_DATA,
			"{\"schemaVersion\":9999,\"completedCount\":42}");

		assertEquals("Data from a newer build must not be interpreted with old rules",
			0, service.load().getCompletedCount());
	}

	@Test
	public void savesAreScopedToTheActiveProfile()
	{
		final RouletteSaveData accountA = new RouletteSaveData();
		accountA.setCompletedCount(7);
		service.save(accountA);

		configManager.setProfileKey("profile-b");
		assertEquals("Account B must not see account A's progress", 0, service.load().getCompletedCount());

		final RouletteSaveData accountB = new RouletteSaveData();
		accountB.setCompletedCount(99);
		service.save(accountB);

		configManager.setProfileKey("profile-a");
		assertEquals(7, service.load().getCompletedCount());
	}

	@Test
	public void savingWithoutAProfileIsANoOp()
	{
		configManager.setProfileKey(null);
		assertFalse(service.isProfileAvailable());

		final RouletteSaveData data = new RouletteSaveData();
		data.setCompletedCount(5);
		service.save(data);

		configManager.setProfileKey("profile-a");
		assertEquals(0, service.load().getCompletedCount());
	}

	@Test
	public void savingStampsTheCurrentSchemaVersion()
	{
		final RouletteSaveData data = new RouletteSaveData();
		data.setSchemaVersion(0);
		service.save(data);

		assertEquals(RouletteSaveData.CURRENT_SCHEMA_VERSION, service.load().getSchemaVersion());
	}

	@Test
	public void savingNullIsIgnored()
	{
		service.save(null);
		assertEquals(0, service.load().getCompletedCount());
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.RouletteActivity;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Integrity checks over the real catalog. These guard the data itself, which is
 * the part most likely to break as activities are added.
 */
public class ActivityCatalogTest
{
	private final ActivityCatalog catalog = new ActivityCatalog();

	@Test
	public void catalogIsNotEmpty()
	{
		assertTrue("The catalog should ship with a usable set of activities", catalog.size() >= 25);
	}

	@Test
	public void activityIdsAreUnique()
	{
		final Set<String> seen = new HashSet<>();
		for (RouletteActivity activity : catalog.getActivities())
		{
			assertTrue("Duplicate activity id: " + activity.getId(), seen.add(activity.getId()));
		}
	}

	@Test
	public void everyActivityIsFullyDescribed()
	{
		for (RouletteActivity activity : catalog.getActivities())
		{
			final String id = activity.getId();

			assertNotNull(id + " has no display name", activity.getDisplayName());
			assertFalse(id + " has an empty display name", activity.getDisplayName().isEmpty());
			assertNotNull(id + " has no type", activity.getType());
			assertNotNull(id + " has no difficulty tier", activity.getDifficulty());
			assertNotNull(id + " has no collection log tab", activity.getTab());
			assertTrue(id + " has no icon item", activity.getIconItemId() > 0);
		}
	}

	@Test
	public void lookupByIdWorksAndIsNullSafe()
	{
		final RouletteActivity barrows = catalog.getById("barrows");

		assertNotNull(barrows);
		assertEquals("Barrows", barrows.getDisplayName());
		assertNull(catalog.getById("no_such_activity"));
		assertNull(catalog.getById(null));
	}

	@Test
	public void itemLookupFindsTheOwningActivity()
	{
		final RouletteActivity barrows = catalog.getById("barrows");
		final int anyBarrowsItem = barrows.getCollectionLogItemIds().iterator().next();

		assertTrue(catalog.findByItemId(anyBarrowsItem).contains(barrows));
	}

	@Test
	public void sharedItemsResolveToEveryOwningActivity()
	{
		// Godsword shards drop from all four God Wars bosses, so the lookup has to
		// be many-valued rather than picking one arbitrarily.
		final RouletteActivity armadyl = catalog.getById("kreearra");
		final RouletteActivity bandos = catalog.getById("general_graardor");

		final Set<Integer> shared = new HashSet<>(armadyl.getCollectionLogItemIds());
		shared.retainAll(bandos.getCollectionLogItemIds());

		assertFalse("The God Wars bosses should share the godsword shards", shared.isEmpty());

		final int sharedItem = shared.iterator().next();
		assertTrue(catalog.findByItemId(sharedItem).contains(armadyl));
		assertTrue(catalog.findByItemId(sharedItem).contains(bandos));
	}

	@Test
	public void unknownItemsBelongToNoActivity()
	{
		assertTrue(catalog.findByItemId(Integer.MAX_VALUE).isEmpty());
	}

	@Test
	public void activitiesThatTrackKillsDeclareNpcs()
	{
		for (RouletteActivity activity : catalog.getActivities())
		{
			if (activity.tracksKills())
			{
				assertFalse(activity.getId() + " claims to track kills but declares no NPCs",
					activity.getRelevantNpcIds().isEmpty());
			}
		}
	}

	@Test
	public void everyActivityEitherMapsItemsOrSaysItCannot()
	{
		// An activity with no items can never auto-complete, so it must carry a
		// note telling the player that confirmation will be needed.
		for (RouletteActivity activity : catalog.getActivities())
		{
			if (activity.getCollectionLogItemIds().isEmpty())
			{
				assertNotNull(activity.getId() + " has no items and no explanatory note",
					activity.getPrerequisiteNote());
			}
		}
	}

	@Test
	public void completionVarbitsAreDistinctExceptWhereThePagesAreShared()
	{
		// The Gauntlet and Corrupted Gauntlet share one in-game log page; nothing
		// else should be doubling up on a varbit.
		final Set<Integer> seen = new HashSet<>();
		final Set<Integer> duplicates = new HashSet<>();

		for (RouletteActivity activity : catalog.getActivities())
		{
			if (activity.hasCompletionVarbit() && !seen.add(activity.getCompletionVarbitId()))
			{
				duplicates.add(activity.getCompletionVarbitId());
			}
		}

		assertEquals("Unexpected shared completion varbits: " + duplicates, 1, duplicates.size());
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.CollectionLogTab;
import com.collectionlogroulette.model.DifficultyTier;
import com.collectionlogroulette.model.RouletteActivity;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.atMost;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ItemResolverTest
{
	private static final int SWORD = 100;
	private static final int SHIELD = 101;

	/** Deliberately shares a display name with {@link #SWORD}. */
	private static final int SWORD_VARIANT = 200;

	private static final int RAID_ITEM = 300;

	private ItemManager itemManager;
	private ItemResolver resolver;
	private ActivityCatalog catalog;
	private RouletteActivity bossActivity;

	@Before
	public void setUp()
	{
		itemManager = mock(ItemManager.class);
		resolver = new ItemResolver(itemManager);

		final Map<Integer, String> names = new HashMap<>();
		names.put(SWORD, "Rune sword");
		names.put(SHIELD, "Dragon shield");
		names.put(SWORD_VARIANT, "Rune sword");
		names.put(RAID_ITEM, "Twisted bow");

		for (Map.Entry<Integer, String> entry : names.entrySet())
		{
			final ItemComposition composition = mock(ItemComposition.class);
			when(composition.getName()).thenReturn(entry.getValue());
			when(itemManager.getItemComposition(entry.getKey())).thenReturn(composition);
		}

		bossActivity = activity("boss", ActivityType.BOSS, SWORD, SHIELD);
		catalog = new ActivityCatalog(Arrays.asList(
			bossActivity,
			activity("other_boss", ActivityType.BOSS, SWORD_VARIANT),
			activity("raid", ActivityType.RAID, RAID_ITEM)));
	}

	private static RouletteActivity activity(String id, ActivityType type, int... items)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(type)
			.difficulty(DifficultyTier.MID)
			.tab(CollectionLogTab.BOSSES)
			.iconItemId(items[0])
			.completionVarbitId(RouletteActivity.NO_VARBIT)
			.enabledByDefault(true)
			.items(items)
			.build();
	}

	@Test
	public void resolvesAnItemInsideTheAssignedActivity()
	{
		assertEquals(SHIELD, resolver.resolveWithinActivity(bossActivity, "Dragon shield"));
	}

	@Test
	public void activityScopedLookupIsCaseAndWhitespaceInsensitive()
	{
		assertEquals(SHIELD, resolver.resolveWithinActivity(bossActivity, "  dRaGoN sHiElD "));
	}

	@Test
	public void activityScopedLookupIgnoresItemsFromElsewhere()
	{
		assertEquals(-1, resolver.resolveWithinActivity(bossActivity, "Twisted bow"));
	}

	@Test
	public void activityScopedLookupPrefersTheAssignedActivitysOwnVariant()
	{
		// "Rune sword" is ambiguous catalog-wide, but inside this activity there
		// is exactly one — which is the whole reason resolution is scoped first.
		assertEquals(SWORD, resolver.resolveWithinActivity(bossActivity, "Rune sword"));
	}

	@Test
	public void nullsAreHandled()
	{
		assertEquals(-1, resolver.resolveWithinActivity(null, "Rune sword"));
		assertEquals(-1, resolver.resolveWithinActivity(bossActivity, null));
		assertEquals(-1, resolver.resolveWithinCatalog(catalog, null));
	}

	@Test
	public void catalogWideLookupFindsAnUnambiguousItem()
	{
		assertEquals(RAID_ITEM, resolver.resolveWithinCatalog(catalog, "Twisted bow"));
	}

	@Test
	public void catalogWideLookupRefusesToGuessBetweenDuplicates()
	{
		// Picking either one could auto-complete the wrong assignment, so the
		// correct answer is to decline and let the player confirm.
		assertEquals(-1, resolver.resolveWithinCatalog(catalog, "Rune sword"));
	}

	@Test
	public void catalogWideLookupReturnsNothingForUnknownNames()
	{
		assertEquals(-1, resolver.resolveWithinCatalog(catalog, "Nonexistent item"));
	}

	@Test
	public void catalogIndexIsBuiltOnceAndReused()
	{
		for (int i = 0; i < 20; i++)
		{
			resolver.resolveWithinCatalog(catalog, "Twisted bow");
		}

		// Four distinct items in the catalog; without caching this would be 80
		// composition lookups on the client thread.
		verify(itemManager, atMost(4)).getItemComposition(anyInt());
	}

	@Test
	public void invalidatingTheCacheForcesARebuild()
	{
		resolver.resolveWithinCatalog(catalog, "Twisted bow");
		resolver.invalidateCache();
		resolver.resolveWithinCatalog(catalog, "Twisted bow");

		// Rebuilt once, so up to two passes over the four items.
		verify(itemManager, atMost(8)).getItemComposition(anyInt());
	}

	@Test
	public void missingCompositionsDoNotBreakResolution()
	{
		when(itemManager.getItemComposition(SHIELD)).thenReturn(null);

		assertEquals(-1, resolver.resolveWithinActivity(bossActivity, "Dragon shield"));
		assertEquals("Other items must still resolve",
			RAID_ITEM, resolver.resolveWithinCatalog(catalog, "Twisted bow"));
	}

	@Test
	public void compositionFailuresAreSwallowed()
	{
		when(itemManager.getItemComposition(SWORD)).thenThrow(new IllegalStateException("cache miss"));

		assertEquals(-1, resolver.resolveWithinActivity(bossActivity, "Rune sword"));
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.TestActivities;
import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.CollectionLogTab;
import com.collectionlogroulette.model.DifficultyTier;
import com.collectionlogroulette.model.RouletteActivity;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Covers the "is the data actually here yet?" logic.
 *
 * <p>This exists because a live client revealed that OSRS does not push the
 * Collection Log slot totals at login — they arrive only when the player opens
 * the log. Every varp reads 0 until then, which is indistinguishable from "no
 * progress" unless you know to check.
 */
public class CollectionLogStateServiceTest
{
	/** Real total obtainable slots is in the thousands; any non-zero will do. */
	private static final int REALISTIC_MAX = 1523;

	private static final int COMPLETE_VARBIT = VarbitID.COLLECTION_BOSSES_BARROWS_COMPLETED;
	private static final int INCOMPLETE_VARBIT = VarbitID.COLLECTION_BOSSES_ZULRAH_COMPLETED;

	private Client client;
	private CollectionLogStateService service;
	private List<RouletteActivity> activities;

	private RouletteActivity finishedPage;
	private RouletteActivity unfinishedPage;
	private RouletteActivity noVarbitPage;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		service = new CollectionLogStateService(client);

		finishedPage = pageWithVarbit("finished", COMPLETE_VARBIT);
		unfinishedPage = pageWithVarbit("unfinished", INCOMPLETE_VARBIT);
		noVarbitPage = TestActivities.minigame("no_varbit");

		activities = Arrays.asList(finishedPage, unfinishedPage, noVarbitPage);

		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getVarbitValue(COMPLETE_VARBIT)).thenReturn(1);
		when(client.getVarbitValue(INCOMPLETE_VARBIT)).thenReturn(0);
	}

	private static RouletteActivity pageWithVarbit(String id, int varbitId)
	{
		return RouletteActivity.builder()
			.id(id)
			.displayName(id)
			.type(ActivityType.BOSS)
			.difficulty(DifficultyTier.MID)
			.tab(CollectionLogTab.BOSSES)
			.iconItemId(1)
			.completionVarbitId(varbitId)
			.enabledByDefault(true)
			.items(1)
			.build();
	}

	private void givenTotals(int obtained, int max)
	{
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT)).thenReturn(obtained);
		when(client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX)).thenReturn(max);
	}

	@Test
	public void completedPageIsTrustedEvenBeforeTheTotalsArrive()
	{
		// A varbit only reads 1 because the server said so — an unpopulated one
		// reads 0. So COMPLETE is never ambiguous.
		givenTotals(0, 0);
		service.refresh(activities);

		assertEquals(CompletionState.COMPLETE, service.getCompletionState(finishedPage));
	}

	@Test
	public void zeroVarbitIsUnknownUntilTheTotalsProveTheDataArrived()
	{
		givenTotals(0, 0);
		service.refresh(activities);

		assertFalse(service.areTotalsSynced());
		assertEquals("A zero varbit with no synced totals could just be undelivered data",
			CompletionState.UNKNOWN, service.getCompletionState(unfinishedPage));
	}

	@Test
	public void zeroVarbitIsIncompleteOnceTheTotalsAreSynced()
	{
		givenTotals(412, REALISTIC_MAX);
		service.refresh(activities);

		assertTrue(service.areTotalsSynced());
		assertEquals(CompletionState.INCOMPLETE, service.getCompletionState(unfinishedPage));
	}

	@Test
	public void totalsAreReportedAsUnknownUntilSynced()
	{
		givenTotals(0, 0);
		service.refresh(activities);

		assertEquals(-1, service.getTotalObtained());
		assertEquals(-1, service.getTotalMax());
	}

	@Test
	public void totalsAreReportedOnceSynced()
	{
		givenTotals(412, REALISTIC_MAX);
		service.refresh(activities);

		assertEquals(412, service.getTotalObtained());
		assertEquals(REALISTIC_MAX, service.getTotalMax());
	}

	@Test
	public void stateUpgradesWhenTheTotalsArriveMidSession()
	{
		// The player logs in, then opens their Collection Log a minute later.
		givenTotals(0, 0);
		service.refresh(activities);
		assertEquals(CompletionState.UNKNOWN, service.getCompletionState(unfinishedPage));

		givenTotals(412, REALISTIC_MAX);
		service.refresh(activities);

		assertEquals(CompletionState.INCOMPLETE, service.getCompletionState(unfinishedPage));
		assertEquals(CompletionState.COMPLETE, service.getCompletionState(finishedPage));
	}

	@Test
	public void activitiesWithoutACompletionVarbitAreAlwaysUnknown()
	{
		givenTotals(412, REALISTIC_MAX);
		service.refresh(activities);

		assertEquals(CompletionState.UNKNOWN, service.getCompletionState(noVarbitPage));
	}

	@Test
	public void nothingIsReadWhileLoggedOut()
	{
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		givenTotals(412, REALISTIC_MAX);

		service.refresh(activities);

		assertEquals(CompletionState.UNKNOWN, service.getCompletionState(finishedPage));
		assertFalse(service.areTotalsSynced());
	}

	@Test
	public void clearForgetsEverythingSoAccountsCannotLeak()
	{
		givenTotals(412, REALISTIC_MAX);
		service.refresh(activities);
		assertEquals(CompletionState.COMPLETE, service.getCompletionState(finishedPage));

		service.clear();

		assertEquals(CompletionState.UNKNOWN, service.getCompletionState(finishedPage));
		assertFalse(service.areTotalsSynced());
		assertEquals(-1, service.getTotalObtained());
	}

	@Test
	public void trackedVarbitsCoverEveryPageAndTheAnnouncementSetting()
	{
		service.initTrackedVarbits(activities);

		assertTrue(service.isTrackedVarbit(COMPLETE_VARBIT));
		assertTrue(service.isTrackedVarbit(INCOMPLETE_VARBIT));
		assertTrue("The announcement setting must trigger a refresh",
			service.isTrackedVarbit(VarbitID.OPTION_COLLECTION_NEW_ITEM));
		assertFalse(service.isTrackedVarbit(VarbitID.COLLECTION_RAIDS_COX_COMPLETED));
	}

	@Test
	public void slotTotalVarpsAreWatchedSoStateCanUpgrade()
	{
		assertTrue(service.isTrackedVarp(VarPlayerID.COLLECTION_COUNT));
		assertTrue(service.isTrackedVarp(VarPlayerID.COLLECTION_COUNT_MAX));
		assertFalse(service.isTrackedVarp(VarPlayerID.COLLECTION_CATEGORY_COUNT));
	}
}

