package com.collectionlogroulette;

import com.collectionlogroulette.service.ActivityCatalog;
import com.collectionlogroulette.service.AssignmentService;
import com.collectionlogroulette.service.ChatCollectionLogDetectionService;
import com.collectionlogroulette.service.CollectionLogDetectionService;
import com.collectionlogroulette.service.CollectionLogStateService;
import com.collectionlogroulette.service.ItemResolver;
import com.collectionlogroulette.service.KillTrackingService;
import com.collectionlogroulette.service.LootTrackingService;
import com.collectionlogroulette.service.PersistenceService;
import com.google.gson.Gson;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Builds the plugin's object graph with mocked RuneLite services.
 *
 * <p>Guice wiring problems — a missing binding, an ambiguous constructor, a
 * dependency cycle — otherwise only surface when the plugin is switched on in a
 * live client. This catches them at build time.
 */
public class DependencyWiringTest
{
	private Injector injector;
	private CollectionLogRoulettePlugin plugin;

	/**
	 * Stands in for the bindings the RuneLite client would normally supply.
	 */
	private static class RuneLiteStubModule extends AbstractModule
	{
		private final CollectionLogRoulettePlugin plugin;

		RuneLiteStubModule(CollectionLogRoulettePlugin plugin)
		{
			this.plugin = plugin;
		}

		@Override
		protected void configure()
		{
			bind(CollectionLogRoulettePlugin.class).toInstance(plugin);

			bind(Client.class).toInstance(mock(Client.class));
			bind(ClientThread.class).toInstance(mock(ClientThread.class));
			bind(ClientToolbar.class).toInstance(mock(ClientToolbar.class));
			bind(OverlayManager.class).toInstance(mock(OverlayManager.class));
			bind(Notifier.class).toInstance(mock(Notifier.class));
			bind(ItemManager.class).toInstance(mock(ItemManager.class));
			bind(Gson.class).toInstance(new Gson());

			// The config itself comes from the plugin's own @Provides method, so it
			// is stubbed one level down at the ConfigManager rather than bound here
			// — binding it directly would collide with that provider.
			final ConfigManager configManager = mock(ConfigManager.class);
			when(configManager.getConfig(CollectionLogRouletteConfig.class)).thenReturn(new TestConfig());
			bind(ConfigManager.class).toInstance(configManager);
		}
	}

	@Before
	public void setUp()
	{
		plugin = new CollectionLogRoulettePlugin();

		// The plugin is itself a Guice module; installing it is what applies its
		// own configure() bindings, exactly as the client does.
		injector = Guice.createInjector(new RuneLiteStubModule(plugin), plugin);
	}

	@Test
	public void configIsSuppliedByThePluginsOwnProvider()
	{
		assertNotNull(injector.getInstance(CollectionLogRouletteConfig.class));
	}

	@Test
	public void everyServiceResolves()
	{
		assertNotNull(injector.getInstance(ActivityCatalog.class));
		assertNotNull(injector.getInstance(AssignmentService.class));
		assertNotNull(injector.getInstance(PersistenceService.class));
		assertNotNull(injector.getInstance(CollectionLogStateService.class));
		assertNotNull(injector.getInstance(LootTrackingService.class));
		assertNotNull(injector.getInstance(KillTrackingService.class));
		assertNotNull(injector.getInstance(ItemResolver.class));
	}

	@Test
	public void detectionServiceIsBoundToTheChatImplementation()
	{
		// This binding lives in the plugin's configure(Binder); if it is dropped,
		// the plugin fails to start with no compile-time warning.
		final CollectionLogDetectionService service =
			injector.getInstance(CollectionLogDetectionService.class);

		assertTrue("CollectionLogDetectionService must resolve to the chat implementation",
			service instanceof ChatCollectionLogDetectionService);
	}

	@Test
	public void servicesThatMustBeSharedAreSingletons()
	{
		// Two AssignmentService instances would mean the panel and the event
		// subscribers were mutating different state.
		assertSame(injector.getInstance(AssignmentService.class),
			injector.getInstance(AssignmentService.class));
		assertSame(injector.getInstance(ActivityCatalog.class),
			injector.getInstance(ActivityCatalog.class));
		assertSame(injector.getInstance(CollectionLogStateService.class),
			injector.getInstance(CollectionLogStateService.class));
		assertSame(injector.getInstance(CollectionLogDetectionService.class),
			injector.getInstance(CollectionLogDetectionService.class));
	}

	@Test
	public void overlayResolvesDespiteItsPluginBackReference()
	{
		// The overlay takes the plugin in its constructor while the plugin holds
		// the overlay as a field — a cycle Guice only tolerates because the field
		// is injected after construction.
		assertNotNull(injector.getInstance(CollectionLogRouletteOverlay.class));
	}

	@Test
	public void catalogIsFullyPopulatedThroughInjection()
	{
		assertTrue(injector.getInstance(ActivityCatalog.class).size() >= 25);
	}
}

package com.collectionlogroulette;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Properties;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards the Plugin Hub packaging contract — the parts that are easy to get
 * wrong when renaming from the template and that only fail at submission time.
 */
public class PluginMetadataTest
{
	private static final Path PROPERTIES = Paths.get("runelite-plugin.properties");

	private static Properties loadProperties() throws IOException
	{
		final Properties properties = new Properties();
		try (InputStream in = Files.newInputStream(PROPERTIES))
		{
			properties.load(in);
		}
		return properties;
	}

	@Test
	public void pluginDescriptorIsPresentAndNamed()
	{
		final PluginDescriptor descriptor =
			CollectionLogRoulettePlugin.class.getAnnotation(PluginDescriptor.class);

		assertNotNull("The plugin class must carry @PluginDescriptor", descriptor);
		assertEquals("Collection Log Roulette", descriptor.name());
		assertFalse("The hub listing needs a description", descriptor.description().isEmpty());
		assertTrue("Tags help users find the plugin", descriptor.tags().length > 0);
	}

	@Test
	public void propertiesFilePointsAtTheRealPluginClass() throws IOException
	{
		final String declared = loadProperties().getProperty("plugins");

		assertEquals(CollectionLogRoulettePlugin.class.getName(), declared);
	}

	@Test
	public void propertiesFileHasNoLeftoverTemplateValues() throws IOException
	{
		final Properties properties = loadProperties();

		for (String key : new String[]{"displayName", "author", "description", "plugins"})
		{
			final String value = properties.getProperty(key);
			assertNotNull("Missing required property: " + key, value);
			assertFalse("Property '" + key + "' is empty", value.trim().isEmpty());
			assertFalse("Property '" + key + "' still has template content: " + value,
				value.toLowerCase().contains("example") || value.contains("com.example"));
		}
	}

	/**
	 * The hub's packager rejects a plugin outright if this key is missing, and it
	 * only finds out after cloning and building — so the failure arrives late and
	 * reads as a build error rather than a metadata one.
	 */
	@Test
	public void buildTypeIsDeclared() throws IOException
	{
		final String build = loadProperties().getProperty("build");

		assertNotNull("runelite-plugin.properties must declare build=standard or build=gradle", build);
		assertTrue("Unexpected build type: " + build,
			"standard".equals(build.trim()) || "gradle".equals(build.trim()));
	}

	@Test
	public void configGroupIsSpecificEnough()
	{
		// The hub rejects generic config groups because they collide across plugins.
		assertEquals("collectionlogroulette", CollectionLogRouletteConfig.GROUP);
	}

	@Test
	public void panelIconResourceExists()
	{
		assertNotNull("The navigation button icon must ship with the jar",
			CollectionLogRoulettePlugin.class.getResourceAsStream("/panel_icon.png"));
	}
}

