package com.collectionlogroulette.model;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Runtime state of the current assignment. Serialised as-is into the save blob.
 *
 * <h2>Timing</h2>
 * Elapsed time is stored as {@link #accumulatedMillis} (banked) plus an open
 * interval starting at {@link #resumedAtMillis}. The plugin banks the open
 * interval on logout, plugin shutdown and completion, which is what keeps the
 * clock from running while RuneLite is closed.
 */
@Data
@NoArgsConstructor
public class Assignment
{
	/** Sentinel meaning "the clock is not currently running". */
	public static final long NOT_RUNNING = 0L;

	private String activityId;
	private AssignmentState state = AssignmentState.NONE;

	/** Wall-clock time the assignment was first rolled. */
	private long startedAtMillis;

	/** Wall-clock time the assignment finished, or 0 while still active. */
	private long endedAtMillis;

	/** Time banked from previously closed tracking intervals. */
	private long accumulatedMillis;

	/** Start of the currently open tracking interval, or {@link #NOT_RUNNING}. */
	private long resumedAtMillis = NOT_RUNNING;

	private List<LootEntry> loot = new ArrayList<>();

	private int killCount;

	@Nullable
	private CollectionLogUnlock unlock;

	private VerificationMethod verification = VerificationMethod.NONE;

	/**
	 * An unlock that was detected while this assignment was active but could not
	 * be attributed to it. Surfaced in the panel with a confirm/dismiss prompt.
	 */
	@Nullable
	private CollectionLogUnlock pendingUnlock;

	public Assignment(String activityId, long nowMillis)
	{
		this.activityId = activityId;
		this.state = AssignmentState.ACTIVE;
		this.startedAtMillis = nowMillis;
		this.accumulatedMillis = 0L;
		this.resumedAtMillis = nowMillis;
	}

	public boolean isActive()
	{
		return state == AssignmentState.ACTIVE;
	}

	public boolean isTimerRunning()
	{
		return resumedAtMillis != NOT_RUNNING;
	}

	public long getElapsedMillis(long nowMillis)
	{
		if (!isTimerRunning())
		{
			return accumulatedMillis;
		}

		// Guard against a clock that jumped backwards; never return less than banked.
		final long open = Math.max(0L, nowMillis - resumedAtMillis);
		return accumulatedMillis + open;
	}

	/** Banks the open interval. Safe to call when already paused. */
	public void pauseTimer(long nowMillis)
	{
		if (!isTimerRunning())
		{
			return;
		}

		accumulatedMillis = getElapsedMillis(nowMillis);
		resumedAtMillis = NOT_RUNNING;
	}

	/** Opens a new tracking interval. Only meaningful for an active assignment. */
	public void resumeTimer(long nowMillis)
	{
		if (isTimerRunning() || state != AssignmentState.ACTIVE)
		{
			return;
		}

		resumedAtMillis = nowMillis;
	}

	/**
	 * Banks the open interval and immediately opens a new one.
	 *
	 * <p>Called before every save so the persisted {@link #accumulatedMillis} is
	 * always current. Without this, a client that dies without a clean shutdown
	 * would leave an open interval whose end is unknown.
	 */
	public void checkpointTimer(long nowMillis)
	{
		if (!isTimerRunning())
		{
			return;
		}

		accumulatedMillis = getElapsedMillis(nowMillis);
		resumedAtMillis = nowMillis;
	}

	/**
	 * Drops the open interval <em>without</em> banking it.
	 *
	 * <p>Used when restoring a save: the interval's start is from a previous
	 * session, so the wall-clock gap since then is time the plugin was not
	 * watching and must not be credited. At most one checkpoint interval of real
	 * playtime is lost, which is the right way to be wrong.
	 */
	public void discardOpenInterval()
	{
		resumedAtMillis = NOT_RUNNING;
	}

	public long getTotalLootValue()
	{
		long total = 0L;
		for (LootEntry entry : getLoot())
		{
			total += entry.isExpense() ? -entry.getTotalValue() : entry.getTotalValue();
		}
		return total;
	}

	public List<LootEntry> getLoot()
	{
		if (loot == null)
		{
			loot = new ArrayList<>();
		}
		return loot;
	}
}

