package com.collectionlogroulette.model;

import com.google.common.collect.ImmutableSet;
import java.util.Collections;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Getter;
import lombok.ToString;

/**
 * Static definition of one rollable Collection Log activity.
 *
 * <p>Instances are immutable and live in {@link
 * com.collectionlogroulette.service.ActivityCatalog}. Nothing here changes at
 * runtime — per-player progress lives in {@link Assignment} and the persisted
 * save data instead.
 */
@Getter
@Builder
@ToString(of = {"id", "displayName", "type"})
public final class RouletteActivity
{
	public static final int NO_VARBIT = -1;

	/** Stable internal identifier. Persisted, so it must never change. */
	private final String id;

	/** Human readable name shown in the panel and overlay. */
	private final String displayName;

	private final ActivityType type;

	private final DifficultyTier difficulty;

	/**
	 * Which Collection Log tab this activity's page lives under. Used to
	 * corroborate unlocks that are not in {@link #collectionLogItemIds}.
	 */
	private final CollectionLogTab tab;

	/** Item used for the activity's icon in the UI. */
	private final int iconItemId;

	/**
	 * Collection Log item IDs belonging to this activity.
	 *
	 * <p>Used to decide whether a detected unlock completes the assignment. The
	 * sets are curated and verified against {@code net.runelite.api.gameval.ItemID}
	 * but are not guaranteed exhaustive — an unlock that is not in this set falls
	 * back to the manual confirmation flow rather than being silently accepted or
	 * silently ignored.
	 */
	private final Set<Integer> collectionLogItemIds;

	/**
	 * NPCs whose deaths count towards this activity's kill counter. Empty when
	 * the activity has no meaningful NPC kill count (clues, most minigames).
	 */
	private final Set<Integer> relevantNpcIds;

	/**
	 * Varbit that the game sets to 1 once every slot on this activity's page has
	 * been obtained, or {@link #NO_VARBIT} when no such varbit is known.
	 */
	private final int completionVarbitId;

	/**
	 * Whether a brand new profile should have this activity switched on. Applied
	 * once, the first time a profile's data is created; after that the player's
	 * own choices in the Activities tab take over.
	 */
	private final boolean enabledByDefault;

	/** Free-form note about requirements, shown in the panel. May be null. */
	@Nullable
	private final String prerequisiteNote;

	public Set<Integer> getCollectionLogItemIds()
	{
		return collectionLogItemIds == null ? Collections.emptySet() : collectionLogItemIds;
	}

	public Set<Integer> getRelevantNpcIds()
	{
		return relevantNpcIds == null ? Collections.emptySet() : relevantNpcIds;
	}

	public boolean hasCompletionVarbit()
	{
		return completionVarbitId != NO_VARBIT;
	}

	public boolean tracksKills()
	{
		return !getRelevantNpcIds().isEmpty();
	}

	public boolean containsItem(int itemId)
	{
		return getCollectionLogItemIds().contains(itemId);
	}

	/**
	 * Builder shortcut so catalog entries read as a plain list of item ids.
	 */
	public static class RouletteActivityBuilder
	{
		public RouletteActivityBuilder items(int... itemIds)
		{
			final ImmutableSet.Builder<Integer> builder = ImmutableSet.builder();
			for (int id : itemIds)
			{
				builder.add(id);
			}
			this.collectionLogItemIds = builder.build();
			return this;
		}

		public RouletteActivityBuilder npcs(int... npcIds)
		{
			final ImmutableSet.Builder<Integer> builder = ImmutableSet.builder();
			for (int id : npcIds)
			{
				builder.add(id);
			}
			this.relevantNpcIds = builder.build();
			return this;
		}
	}
}

