package com.collectionlogroulette.model;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Data;

/**
 * Everything persisted for a single RuneScape account profile.
 *
 * <p>Serialised to JSON and stored via {@code ConfigManager}'s RS-profile aware
 * API, which is what keeps two accounts from sharing progress.
 *
 * <h2>Versioning</h2>
 * {@link #schemaVersion} is written on every save. Loading data with a newer
 * version than {@link #CURRENT_SCHEMA_VERSION}, or data that fails to parse at
 * all, is treated as "no save" rather than as an error the client should die on.
 */
@Data
public class RouletteSaveData
{
	public static final int CURRENT_SCHEMA_VERSION = 1;

	/** Cap on retained history entries; oldest are dropped first. */
	public static final int MAX_HISTORY = 100;

	private int schemaVersion = CURRENT_SCHEMA_VERSION;

	@Nullable
	private Assignment currentAssignment;

	/** Activity id of the most recent roll, used to avoid immediate repeats. */
	@Nullable
	private String previousActivityId;

	private int completedCount;
	private int currentStreak;
	private int bestStreak;
	private int availableSkips;
	private int totalSkipped;
	private int unlocksEarned;

	/**
	 * Completions counted towards the next earned skip. Reset each time a skip
	 * is granted, so changing the "completions per skip" setting mid-run behaves
	 * sensibly instead of retroactively granting a pile of skips.
	 */
	private int completionsTowardsNextSkip;

	/**
	 * Set once the catalog's {@code enabledByDefault} flags have been applied to
	 * this profile. Without it, re-applying defaults on every load would silently
	 * undo the player's own choices.
	 */
	private boolean defaultsApplied;

	/** Activity ids the player has manually excluded from rolls. */
	private Set<String> excludedActivityIds = new LinkedHashSet<>();

	/**
	 * Item ids this plugin has itself seen unlocked. Acts as a local cache in the
	 * fallback hierarchy when the game's own varbits cannot answer a question.
	 */
	private Set<Integer> observedUnlockItemIds = new HashSet<>();

	private List<AssignmentHistoryEntry> history = new ArrayList<>();

	public Set<String> getExcludedActivityIds()
	{
		if (excludedActivityIds == null)
		{
			excludedActivityIds = new LinkedHashSet<>();
		}
		return excludedActivityIds;
	}

	public Set<Integer> getObservedUnlockItemIds()
	{
		if (observedUnlockItemIds == null)
		{
			observedUnlockItemIds = new HashSet<>();
		}
		return observedUnlockItemIds;
	}

	public List<AssignmentHistoryEntry> getHistory()
	{
		if (history == null)
		{
			history = new ArrayList<>();
		}
		return history;
	}

	public void addHistoryEntry(AssignmentHistoryEntry entry)
	{
		final List<AssignmentHistoryEntry> entries = getHistory();
		entries.add(0, entry);
		while (entries.size() > MAX_HISTORY)
		{
			entries.remove(entries.size() - 1);
		}
	}
}

