public class CollectionLogRoulettePlugin extends Plugin
{
	/** How often the panel's elapsed clock ticks, in milliseconds. */
	private static final int TIMER_INTERVAL_MILLIS = 1000;

	/** Periodic autosave cadence, in game ticks (~60s at 0.6s per tick). */
	private static final int AUTOSAVE_TICKS = 100;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Notifier notifier;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private CollectionLogRouletteConfig config;

	@Inject
	private ActivityCatalog catalog;

	@Inject
	private AssignmentService assignmentService;

	@Inject
	private CollectionLogStateService logStateService;

	@Inject
	private CollectionLogDetectionService detectionService;

	@Inject
	private LootTrackingService lootTrackingService;

	@Inject
	private KillTrackingService killTrackingService;

	@Inject
	private ItemResolver itemResolver;

	@Inject
	private CollectionLogRouletteOverlay overlay;

	private CollectionLogRoulettePanel panel;
	private NavigationButton navButton;
	private Timer uiTimer;

	/** Set when a notification script starts, consumed when it finishes. */
	private boolean notificationPending;

	private int ticksSinceSave;

	/**
	 * Last observed value of the in-game announcement setting, so it is logged on
	 * change rather than on every refresh. -2 means "never read".
	 */
	private int lastAnnouncementSetting = -2;

	/** De-duplicates NPC loot that arrives via more than one event. */
	private int lastNpcLootId = -1;
	private int lastNpcLootTick = -1;

	@Override
	public void configure(Binder binder)
	{
		binder.bind(CollectionLogDetectionService.class).to(ChatCollectionLogDetectionService.class);
	}

	@Provides
	CollectionLogRouletteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CollectionLogRouletteConfig.class);
	}

	@Override
	protected void startUp()
	{
		logStateService.initTrackedVarbits(catalog.getActivities());
		assignmentService.setCompletionLookup(logStateService::getCompletionState);
		assignmentService.loadForCurrentProfile();

		panel = new CollectionLogRoulettePanel(
			assignmentService, catalog, logStateService, config, itemManager, gson);

		assignmentService.addChangeListener(() -> panel.refresh());
		assignmentService.addCompletionListener(this::onAssignmentCompleted);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Collection Log Roulette")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		// A Swing timer fires on the EDT, so the clock refresh needs no extra
		// thread and no marshalling.
		uiTimer = new Timer(TIMER_INTERVAL_MILLIS, e -> panel.tickTimer());
		uiTimer.start();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::refreshLogState);
			assignmentService.resumeTimer();
		}

		panel.refresh();
		log.debug("Collection Log Roulette started with {} activities", catalog.size());
	}

	@Override
	protected void shutDown()
	{
		// Bank whatever time is open so it does not keep running while we are off.
		assignmentService.pauseTimer();

		if (!config.keepAssignmentOnDisable())
		{
			assignmentService.resetCurrent();
		}

		assignmentService.save();
		assignmentService.clearChangeListeners();

		if (uiTimer != null)
		{
			uiTimer.stop();
			uiTimer = null;
		}

		overlayManager.remove(overlay);

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		panel = null;

		detectionService.reset();
		killTrackingService.reset();
		itemResolver.invalidateCache();
		logStateService.clear();
		assignmentService.unload();

		log.debug("Collection Log Roulette stopped");
	}

	// ------------------------------------------------------------------
	// Lifecycle events
	// ------------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				clientThread.invokeLater(this::refreshLogState);
				assignmentService.resumeTimer();
				break;

			case LOGIN_SCREEN:
			case HOPPING:
			case CONNECTION_LOST:
				if (config.pauseTimerWhileLoggedOut())
				{
					assignmentService.pauseTimer();
				}
				assignmentService.save();
				detectionService.reset();
				killTrackingService.reset();
				break;

			default:
				break;
		}
	}

	/**
	 * Fired when the active RuneScape account changes. Progress is stored per
	 * profile, so this swaps the whole in-memory state rather than merging.
	 */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		log.debug("RuneScape profile changed; reloading roulette data");

		assignmentService.pauseTimer();
		logStateService.clear();
		detectionService.reset();
		killTrackingService.reset();

		assignmentService.loadForCurrentProfile();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::refreshLogState);
			assignmentService.resumeTimer();
		}
	}

	/**
	 * Content filters, difficulty range and skip rules all change what the panel
	 * should show, so it has to redraw when they do — otherwise the eligible
	 * count and the Roll/Skip button states stay stale until something else
	 * happens to trigger a refresh.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CollectionLogRouletteConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		final CollectionLogRoulettePanel current = panel;
		if (current != null)
		{
			current.refresh();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (assignmentService.getCurrentAssignment() == null)
		{
			return;
		}

		if (++ticksSinceSave >= AUTOSAVE_TICKS)
		{
			ticksSinceSave = 0;
			assignmentService.save();
		}
	}

	// ------------------------------------------------------------------
	// Collection log state
	// ------------------------------------------------------------------

	/** Must run on the client thread. */
	private void refreshLogState()
	{
		logStateService.refresh(catalog.getActivities());

		// Log the raw value, and only when it changes. A one-shot "disabled"
		// message cannot distinguish a real setting from a varbit we read before
		// the server delivered it, which is exactly the trap the slot totals set.
		final int announcementSetting = logStateService.getAnnouncementSetting();
		if (announcementSetting != lastAnnouncementSetting)
		{
			lastAnnouncementSetting = announcementSetting;
			log.debug("Collection log announcement setting is now {} ({})",
				announcementSetting,
				announcementSetting > 0 ? "detection can work" : "detection cannot work");
		}

		if (announcementSetting == 0)
		{
			showNotice("Collection log announcements are turned off in-game. "
				+ "Automatic detection will not work until you re-enable them in "
				+ "Settings → All Settings → Chat → \"Collection log - New item\".", true);
		}
		else
		{
			showNotice(null, false);
		}

		if (panel != null)
		{
			panel.refresh();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// A varbit id of -1 means the underlying varp changed without mapping to a
		// varbit we asked about — that is how the collection log slot totals
		// arrive when the player opens the log, so both cases matter here.
		final boolean relevant = event.getVarbitId() == -1
			? logStateService.isTrackedVarp(event.getVarpId())
			: logStateService.isTrackedVarbit(event.getVarbitId());

		if (!relevant)
		{
			return;
		}

		// Already on the client thread here, so read directly.
		refreshLogState();
	}

	// ------------------------------------------------------------------
	// Unlock detection
	// ------------------------------------------------------------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
		{
			return;
		}

		detectionService.detectUnlock(event.getMessage(), System.currentTimeMillis())
			.ifPresent(this::handleUnlock);
	}

	/**
	 * The pop-up variant of the same announcement. The item name is only in the
	 * client varcs once the notification script has run, so the flag is raised on
	 * the start script and read when the delay script finishes.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.NOTIFICATION_START)
		{
			notificationPending = true;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.NOTIFICATION_DELAY || !notificationPending)
		{
			return;
		}

		notificationPending = false;

		final String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
		final String body = client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN);

		detectionService.detectUnlockFromNotification(title, body, System.currentTimeMillis())
			.ifPresent(this::handleUnlock);
	}

	/**
	 * Resolves the announced item to an id and offers it to the assignment.
	 * Runs on the client thread, which is required for the item cache lookups.
	 */
	private void handleUnlock(CollectionLogUnlock unlock)
	{
		final RouletteActivity activity = assignmentService.getCurrentActivity();

		// Prefer matching within the assigned activity: exact, and free of the
		// ambiguity a global name search would introduce.
		int itemId = itemResolver.resolveWithinActivity(activity, unlock.getItemName());
		if (itemId == -1)
		{
			itemId = itemResolver.resolveWithinCatalog(catalog, unlock.getItemName());
		}

		if (itemId != -1)
		{
			unlock.setItemId(itemId);
		}
		else
		{
			log.debug("Could not resolve collection log item '{}' to an id", unlock.getItemName());
		}

		final UnlockOutcome outcome = assignmentService.offerUnlock(unlock);
		log.debug("Unlock '{}' (id {}) -> {}", unlock.getItemName(), unlock.getItemId(), outcome);

		if (outcome == UnlockOutcome.NEEDS_CONFIRMATION)
		{
			showNotice("Detected \"" + unlock.getItemName() + "\" but could not confirm it belongs "
				+ "to your assignment. Check the Roulette tab.", false);
		}
	}

	private void onAssignmentCompleted(RouletteActivity activity, CollectionLogUnlock unlock)
	{
		notifier.notify(config.completionNotification(),
			"Collection Log Roulette: " + activity.getDisplayName() + " complete! ("
				+ unlock.getItemName() + ")");

		showNotice(null, false);
	}

	// ------------------------------------------------------------------
	// Loot and kills
	// ------------------------------------------------------------------

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		final NPC npc = event.getNpc();
		if (npc == null || !acceptNpcLoot(npc.getId()))
		{
			return;
		}

		lootTrackingService.recordLoot(event.getItems(), npc.getName());
		killTrackingService.onNpcKilled(npc.getId(), client.getTickCount());
	}

	/**
	 * Newer server-authoritative NPC loot. Shares the de-duplication key with
	 * {@link #onNpcLootReceived} so a kill reported through both paths is only
	 * counted once.
	 */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (event.getComposition() == null || !acceptNpcLoot(event.getComposition().getId()))
		{
			return;
		}

		lootTrackingService.recordLoot(event.getItems(), event.getComposition().getName());
		killTrackingService.onNpcKilled(event.getComposition().getId(), client.getTickCount());
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		lootTrackingService.recordLoot(event.getItems(),
			event.getPlayer() == null ? "Player" : event.getPlayer().getName());
	}

	/**
	 * Chest, casket and minigame-reward loot. This is the only supported route to
	 * raid chests and clue caskets, which never surface as NPC drops.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		lootTrackingService.recordLoot(event.getItems(), event.getName());
	}

	private boolean acceptNpcLoot(int npcId)
	{
		final int tick = client.getTickCount();
		if (npcId == lastNpcLootId && tick == lastNpcLootTick)
		{
			return false;
		}

		lastNpcLootId = npcId;
		lastNpcLootTick = tick;
		return true;
	}

	private void showNotice(String message, boolean error)
	{
		final CollectionLogRoulettePanel current = panel;
		if (current == null)
		{
			return;
		}

		SwingUtilities.invokeLater(() -> current.setNotice(message, error));
	}
}

package com.collectionlogroulette.ui;

import com.collectionlogroulette.CollectionLogRouletteConfig;
import com.collectionlogroulette.service.ActivityCatalog;
import com.collectionlogroulette.service.AssignmentService;
import com.collectionlogroulette.service.CollectionLogStateService;
import com.google.gson.Gson;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

/**
 * Root side panel. Owns the three tabs and the shared notice banner.
 *
 * <p>Every mutating method here must run on the Swing EDT; {@link #refresh()} is
 * the single entry point the plugin calls and it marshals itself.
 */
public class CollectionLogRoulettePanel extends PluginPanel
{
	private final CollectionLogRouletteConfig config;

	private final CurrentAssignmentPanel currentPanel;
	private final HistoryPanel historyPanel;
	private final ActivitySettingsPanel activityPanel;

	private final JLabel noticeLabel = new JLabel();
	private final JPanel noticeWrapper = new JPanel(new BorderLayout());

	public CollectionLogRoulettePanel(
		AssignmentService assignmentService,
		ActivityCatalog catalog,
		CollectionLogStateService logStateService,
		CollectionLogRouletteConfig config,
		ItemManager itemManager,
		Gson gson)
	{
		super(false);
		this.config = config;

		this.currentPanel = new CurrentAssignmentPanel(assignmentService, logStateService, itemManager);
		this.historyPanel = new HistoryPanel(assignmentService, gson);
		this.activityPanel = new ActivitySettingsPanel(catalog, assignmentService);

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		add(buildNorth(), BorderLayout.NORTH);
		add(buildTabs(), BorderLayout.CENTER);
	}

	private JPanel buildNorth()
	{
		final JPanel north = new JPanel();
		north.setLayout(new BoxLayout(north, BoxLayout.Y_AXIS));
		north.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JLabel heading = new JLabel("Collection Log Roulette");
		heading.setFont(FontManager.getRunescapeBoldFont());
		heading.setForeground(java.awt.Color.WHITE);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		north.add(heading);
		north.add(UiUtils.gap(6));

		noticeLabel.setFont(FontManager.getRunescapeSmallFont());
		noticeWrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		noticeWrapper.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		noticeWrapper.add(noticeLabel, BorderLayout.CENTER);
		noticeWrapper.setVisible(false);
		noticeWrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		noticeWrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, 60));
		north.add(noticeWrapper);

		return north;
	}

	private JPanel buildTabs()
	{
		// The tab group swaps the selected tab's content into this display panel.
		final JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);

		final MaterialTabGroup tabs = new MaterialTabGroup(display);
		tabs.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));

		final MaterialTab current = new MaterialTab("Roulette", tabs, wrapScrollable(currentPanel));
		final MaterialTab history = new MaterialTab("History", tabs, wrapScrollable(historyPanel));
		final MaterialTab activities = new MaterialTab("Activities", tabs, wrapScrollable(activityPanel));

		tabs.addTab(current);
		tabs.addTab(history);
		tabs.addTab(activities);
		tabs.select(current);

		final JPanel container = new JPanel(new BorderLayout());
		container.setBackground(ColorScheme.DARK_GRAY_COLOR);
		container.add(tabs, BorderLayout.NORTH);
		container.add(display, BorderLayout.CENTER);
		return container;
	}

	/**
	 * BoxLayout columns want to stretch; pinning them to the top of a BorderLayout
	 * keeps content compact when it is shorter than the panel.
	 */
	private static JPanel wrapScrollable(JPanel content)
	{
		final JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(content, BorderLayout.NORTH);
		return wrapper;
	}

	/**
	 * Full rebuild of every tab. Safe to call from any thread.
	 */
	public void refresh()
	{
		SwingUtilities.invokeLater(() ->
		{
			currentPanel.rebuild();
			historyPanel.rebuild();
			activityPanel.rebuild();
		});
	}

	/** Per-second elapsed-time update. Must be called on the EDT. */
	public void tickTimer()
	{
		currentPanel.tick();
	}

	/**
	 * Shows a banner at the top of the panel.
	 *
	 * @param message text to show, or null to hide the banner
	 * @param error   whether to style it as an error rather than information
	 */
	public void setNotice(@Nullable String message, boolean error)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (message == null || !config.showPanelNotices())
			{
				noticeWrapper.setVisible(false);
				return;
			}

			noticeLabel.setText("<html><body style='width:170px'>" + message + "</body></html>");
			noticeLabel.setForeground(error ? UiUtils.ERROR : UiUtils.WARNING);
			noticeWrapper.setVisible(true);
			noticeWrapper.revalidate();
			noticeWrapper.repaint();
		});
	}
}

package com.collectionlogroulette.ui;

import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.RouletteActivity;
import com.collectionlogroulette.service.ActivityCatalog;
import com.collectionlogroulette.service.AssignmentService;
import com.collectionlogroulette.service.CompletionState;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Per-activity include/exclude toggles.
 *
 * <p>These live here rather than in the config page on purpose: thirty-odd
 * individual checkboxes would make the settings screen unusable.
 */
public class ActivitySettingsPanel extends JPanel
{
	private final ActivityCatalog catalog;
	private final AssignmentService assignmentService;

	public ActivitySettingsPanel(ActivityCatalog catalog, AssignmentService assignmentService)
	{
		this.catalog = catalog;
		this.assignmentService = assignmentService;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
	}

	public void rebuild()
	{
		removeAll();

		final JPanel header = UiUtils.section();
		header.add(UiUtils.title("ACTIVITIES"));
		header.add(UiUtils.gap(4));

		final List<RouletteActivity> eligible = assignmentService.getEligibleActivities();
		header.add(UiUtils.body(eligible.size() + " of " + catalog.size() + " currently eligible"));
		header.add(UiUtils.gap(6));

		final JLabel hint = new JLabel("<html><body style='width:170px'>"
			+ "Unticking an activity keeps it out of future rolls. Activities the game reports as "
			+ "fully collected are excluded automatically.</body></html>");
		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		hint.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(hint);
		header.add(UiUtils.gap(8));

		final JPanel bulk = new JPanel();
		bulk.setLayout(new BoxLayout(bulk, BoxLayout.X_AXIS));
		bulk.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bulk.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JButton all = UiUtils.button("Enable all");
		all.addActionListener(e -> setAll(false));
		final JButton none = UiUtils.button("Disable all");
		none.addActionListener(e -> setAll(true));

		bulk.add(all);
		bulk.add(UiUtils.gap(4));
		bulk.add(none);
		bulk.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		header.add(bulk);

		add(header);
		add(UiUtils.gap(6));

		for (Map.Entry<ActivityType, List<RouletteActivity>> group : groupByType().entrySet())
		{
			add(buildGroup(group.getKey(), group.getValue()));
			add(UiUtils.gap(6));
		}

		revalidate();
		repaint();
	}

	private Map<ActivityType, List<RouletteActivity>> groupByType()
	{
		final Map<ActivityType, List<RouletteActivity>> grouped = new EnumMap<>(ActivityType.class);
		for (RouletteActivity activity : catalog.getActivities())
		{
			grouped.computeIfAbsent(activity.getType(), k -> new java.util.ArrayList<>()).add(activity);
		}

		// EnumMap already orders by the enum's own declaration order, which reads
		// bosses -> raids -> minigames -> clues -> skilling -> other.
		return new LinkedHashMap<>(grouped);
	}

	private JPanel buildGroup(ActivityType type, List<RouletteActivity> activities)
	{
		final JPanel section = UiUtils.section();

		final JLabel heading = new JLabel(type.getDisplayName().toUpperCase());
		heading.setFont(FontManager.getRunescapeSmallFont());
		heading.setForeground(ColorScheme.BRAND_ORANGE);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(heading);
		section.add(UiUtils.gap(4));

		for (RouletteActivity activity : activities)
		{
			section.add(buildRow(activity));
		}

		return section;
	}

	private JPanel buildRow(RouletteActivity activity)
	{
		final JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JCheckBox toggle = new JCheckBox(activity.getDisplayName());
		toggle.setSelected(!assignmentService.isExcluded(activity.getId()));
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		toggle.setForeground(Color.WHITE);
		toggle.setFocusPainted(false);
		toggle.addActionListener(e ->
			assignmentService.setExcluded(activity.getId(), !toggle.isSelected()));

		final CompletionState state = assignmentService.getCompletionState(activity);
		if (state == CompletionState.COMPLETE)
		{
			toggle.setForeground(UiUtils.SUCCESS);
			toggle.setToolTipText("Every slot on this Collection Log page is already obtained.");
		}
		else if (state == CompletionState.UNKNOWN)
		{
			toggle.setToolTipText("Collection Log state for this activity is unknown right now.");
		}

		row.add(toggle, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, toggle.getPreferredSize().height + 2));
		return row;
	}

	private void setAll(boolean excluded)
	{
		final List<String> ids = catalog.getActivities().stream()
			.map(RouletteActivity::getId)
			.collect(Collectors.toList());

		// One call, so the panel rebuilds once rather than once per activity.
		assignmentService.setExcluded(ids, excluded);
	}
}

package com.collectionlogroulette.ui;

import com.collectionlogroulette.model.Assignment;
import com.collectionlogroulette.model.AssignmentState;
import com.collectionlogroulette.model.CollectionLogUnlock;
import com.collectionlogroulette.model.RouletteActivity;
import com.collectionlogroulette.model.RouletteSaveData;
