/**
 * The main section of the side panel: what you are doing right now, how it is
 * going, and the four actions that change it.
 *
 * <p>Rebuilt wholesale on {@link #rebuild()} because the three states show quite
 * different content; the elapsed clock updates in place via {@link #tick()} so
 * the once-a-second refresh does not thrash the layout.
 */
public class CurrentAssignmentPanel extends JPanel
{
	private static final SimpleDateFormat START_TIME_FORMAT = new SimpleDateFormat("d MMM, HH:mm");

	private final AssignmentService assignmentService;
	private final CollectionLogStateService logStateService;
	private final ItemManager itemManager;

	// Live fields updated by tick() without a full rebuild, so loot and kills stay
	// current without relayouting the panel on every drop.
	@Nullable
	private JLabel elapsedValue;

	@Nullable
	private JLabel lootValue;

	@Nullable
	private JLabel killValue;

	public CurrentAssignmentPanel(AssignmentService assignmentService,
		CollectionLogStateService logStateService, ItemManager itemManager)
	{
		this.assignmentService = assignmentService;
		this.logStateService = logStateService;
		this.itemManager = itemManager;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
	}

	public void rebuild()
	{
		removeAll();
		elapsedValue = null;
		lootValue = null;
		killValue = null;

		final AssignmentState state = assignmentService.getState();
		switch (state)
		{
			case ACTIVE:
				buildActive();
				break;
			case COMPLETED:
				buildCompleted();
				break;
			case NONE:
			default:
				buildIdle();
				break;
		}

		add(UiUtils.gap(8));
		add(buildStats());

		revalidate();
		repaint();
	}

	/** Cheap per-second update of the live fields, with no relayout. */
	public void tick()
	{
		final Assignment assignment = assignmentService.getCurrentAssignment();
		if (assignment == null)
		{
			return;
		}

		if (elapsedValue != null)
		{
			elapsedValue.setText(UiUtils.formatDuration(assignmentService.getElapsedMillis()));
		}

		if (lootValue != null)
		{
			lootValue.setText(UiUtils.formatGp(assignment.getTotalLootValue()));
		}

		if (killValue != null)
		{
			killValue.setText(Integer.toString(assignment.getKillCount()));
		}
	}

	// ------------------------------------------------------------------
	// States
	// ------------------------------------------------------------------

	private void buildIdle()
	{
		final JPanel section = UiUtils.section();
		section.add(UiUtils.title("COLLECTION LOG ROULETTE"));
		section.add(UiUtils.gap(6));

		final JLabel blurb = new JLabel("<html><body style='width:170px'>"
			+ "Spin for a Collection Log activity, then obtain any new slot from it."
			+ "</body></html>");
		blurb.setFont(FontManager.getRunescapeSmallFont());
		blurb.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		blurb.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(blurb);
		section.add(UiUtils.gap(8));

		final int eligible = assignmentService.getEligibleActivities().size();
		final boolean loggedIn = assignmentService.isPersistenceAvailable();

		section.add(UiUtils.statRow("Eligible activities", UiUtils.valueLabel(Integer.toString(eligible))));
		section.add(UiUtils.statRow("Available skips",
			UiUtils.valueLabel(Integer.toString(assignmentService.getData().getAvailableSkips()))));
		section.add(UiUtils.gap(10));

		final JButton roll = UiUtils.primaryButton("ROLL ASSIGNMENT");
		roll.setEnabled(loggedIn && eligible > 0);
		roll.addActionListener(e -> doRoll());
		section.add(roll);

		// Progress is stored per account, so rolling before login would produce an
		// assignment that login then quietly replaced.
		if (!loggedIn)
		{
			section.add(UiUtils.gap(6));
			section.add(warning("Log in to a RuneScape account to start. Progress is stored per account."));
		}
		else if (eligible == 0)
		{
			section.add(UiUtils.gap(6));
			section.add(warning(
				"Nothing is eligible. Widen the content filters, or re-enable activities below."));
		}

		add(section);
	}

	private void buildActive()
	{
		final Assignment assignment = assignmentService.getCurrentAssignment();
		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (assignment == null || activity == null)
		{
			buildIdle();
			return;
		}

		final JPanel section = UiUtils.section();
		section.add(UiUtils.title("CURRENT ASSIGNMENT"));
		section.add(UiUtils.gap(6));
		section.add(buildActivityHeader(activity));
		section.add(UiUtils.gap(4));

		final JLabel goal = new JLabel("<html><body style='width:170px'>Obtain any new "
			+ escape(activity.getDisplayName()) + " Collection Log slot.</body></html>");
		goal.setFont(FontManager.getRunescapeSmallFont());
		goal.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		goal.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(goal);

		if (activity.getPrerequisiteNote() != null)
		{
			section.add(UiUtils.gap(4));
			final JLabel note = new JLabel("<html><body style='width:170px'>"
				+ escape(activity.getPrerequisiteNote()) + "</body></html>");
			note.setFont(FontManager.getRunescapeSmallFont());
			note.setForeground(UiUtils.WARNING);
			note.setAlignmentX(Component.LEFT_ALIGNMENT);
			section.add(note);
		}

		section.add(UiUtils.gap(8));

		elapsedValue = UiUtils.valueLabel(UiUtils.formatDuration(assignmentService.getElapsedMillis()));
		section.add(UiUtils.statRow("Time", elapsedValue));

		final JLabel status = UiUtils.valueLabel(assignment.isTimerRunning() ? "Active" : "Paused");
		status.setForeground(assignment.isTimerRunning() ? UiUtils.SUCCESS : UiUtils.WARNING);
		section.add(UiUtils.statRow("Status", status));

		section.add(UiUtils.statRow("Started", UiUtils.valueLabel(
			START_TIME_FORMAT.format(new Date(assignment.getStartedAtMillis())))));

		lootValue = UiUtils.valueLabel(UiUtils.formatGp(assignment.getTotalLootValue()));
		section.add(UiUtils.statRow("Est. loot", lootValue));
		section.add(buildKillRow(activity, assignment, true));

		final JLabel disclaimer = new JLabel("<html><body style='width:170px'>"
			+ "Loot value is estimated from tracked drops at GE prices. It is not profit — "
			+ "supplies are not counted.</body></html>");
		disclaimer.setFont(FontManager.getRunescapeSmallFont());
		disclaimer.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		disclaimer.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(UiUtils.gap(4));
		section.add(disclaimer);

		add(section);

		if (assignment.getPendingUnlock() != null)
		{
			add(UiUtils.gap(6));
			add(buildPendingUnlockPrompt(assignment.getPendingUnlock(), activity));
		}

		add(UiUtils.gap(8));
		add(buildActiveButtons());
	}

	private void buildCompleted()
	{
		final Assignment assignment = assignmentService.getCurrentAssignment();
		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (assignment == null || activity == null)
		{
			buildIdle();
			return;
		}

		final JPanel section = UiUtils.section();

		final JLabel heading = UiUtils.title("ASSIGNMENT COMPLETE");
		heading.setForeground(UiUtils.SUCCESS);
		section.add(heading);
		section.add(UiUtils.gap(6));
		section.add(buildActivityHeader(activity));
		section.add(UiUtils.gap(6));

		final CollectionLogUnlock unlock = assignment.getUnlock();
		if (unlock != null)
		{
			section.add(buildUnlockRow(unlock));
			section.add(UiUtils.gap(6));
		}

		section.add(UiUtils.statRow("Time",
			UiUtils.valueLabel(UiUtils.formatDuration(assignment.getAccumulatedMillis()))));
		section.add(UiUtils.statRow("Est. loot",
			UiUtils.valueLabel(UiUtils.formatGp(assignment.getTotalLootValue()))));
		section.add(buildKillRow(activity, assignment, false));

		final JLabel verification = UiUtils.valueLabel(assignment.getVerification().getDisplayName());
		switch (assignment.getVerification())
		{
			case AUTOMATIC:
				verification.setForeground(UiUtils.SUCCESS);
				break;
			case MANUAL:
				verification.setForeground(UiUtils.WARNING);
				verification.setToolTipText("You confirmed this completion; the plugin did not verify it.");
				break;
			default:
				verification.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				break;
		}
		section.add(UiUtils.statRow("Verified", verification));

		add(section);
		add(UiUtils.gap(8));

		final JButton next = UiUtils.primaryButton("ROLL NEXT ASSIGNMENT");
		next.addActionListener(e -> doRoll());
		add(next);
	}

	// ------------------------------------------------------------------
	// Pieces
	// ------------------------------------------------------------------

	private JPanel buildActivityHeader(RouletteActivity activity)
	{
		final JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		// AsyncBufferedImage repaints the label itself once the sprite arrives.
		itemManager.getImage(activity.getIconItemId()).addTo(icon);
		header.add(icon, BorderLayout.WEST);

		final JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		final JLabel name = new JLabel(activity.getDisplayName());
		name.setFont(UiUtils.smallBold());
		name.setForeground(Color.WHITE);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel type = new JLabel(activity.getType().getDisplayName()
			+ " · " + activity.getDifficulty().getDisplayName());
		type.setFont(FontManager.getRunescapeSmallFont());
		type.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		type.setAlignmentX(Component.LEFT_ALIGNMENT);

		text.add(name);
		text.add(type);
		header.add(text, BorderLayout.CENTER);

		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));
		return header;
	}

	private JPanel buildUnlockRow(CollectionLogUnlock unlock)
	{
		final JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (unlock.hasItemId())
		{
			final JLabel icon = new JLabel();
			icon.setPreferredSize(new Dimension(32, 32));
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			itemManager.getImage(unlock.getItemId()).addTo(icon);
			row.add(icon, BorderLayout.WEST);
		}

		final JLabel name = new JLabel("<html><body style='width:150px'>New unlock: <b>"
			+ escape(unlock.getItemName()) + "</b></body></html>");
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(UiUtils.SUCCESS);
		row.add(name, BorderLayout.CENTER);

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		return row;
	}

	/**
	 * Kill counters only exist where an activity declared NPC ids. Everything
	 * else says so plainly rather than showing a zero that means nothing.
	 */
	private JPanel buildKillRow(RouletteActivity activity, Assignment assignment, boolean live)
	{
		if (activity.tracksKills())
		{
			final JLabel kills = UiUtils.valueLabel(Integer.toString(assignment.getKillCount()));
			if (live)
			{
				killValue = kills;
			}
			return UiUtils.statRow("Kills", kills);
		}

		final JLabel label = UiUtils.valueLabel("Not tracked");
		label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		label.setToolTipText("Completions are not automatically available for this activity.");
		return UiUtils.statRow("Completions", label);
	}

	private JPanel buildPendingUnlockPrompt(CollectionLogUnlock unlock, RouletteActivity activity)
	{
		final JPanel section = UiUtils.section();
		section.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, UiUtils.WARNING),
			BorderFactory.createEmptyBorder(8, 8, 8, 8)));

		final JLabel heading = UiUtils.title("UNVERIFIED UNLOCK");
		heading.setForeground(UiUtils.WARNING);
		section.add(heading);
		section.add(UiUtils.gap(4));

		final JLabel text = new JLabel("<html><body style='width:170px'>Detected <b>"
			+ escape(unlock.getItemName()) + "</b>, but this plugin cannot confirm it belongs to "
			+ escape(activity.getDisplayName()) + ".<br><br>Does it?</body></html>");
		text.setFont(FontManager.getRunescapeSmallFont());
		text.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		text.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(text);
		section.add(UiUtils.gap(6));

		final JButton yes = UiUtils.button("Yes — complete assignment");
		yes.addActionListener(e -> assignmentService.confirmPendingUnlock());
		section.add(yes);
		section.add(UiUtils.gap(4));

		final JButton no = UiUtils.button("No — keep going");
		no.addActionListener(e -> assignmentService.dismissPendingUnlock());
		section.add(no);

		return section;
	}

	private JPanel buildActiveButtons()
	{
		final JPanel buttons = UiUtils.column();

		final JButton skip = UiUtils.button("SKIP");
		skip.setEnabled(assignmentService.canSkip());
		skip.setToolTipText(assignmentService.canSkip()
			? "Abandon this assignment and spend a skip"
			: "No skips available");
		skip.addActionListener(e -> doSkip());
		buttons.add(skip);
		buttons.add(UiUtils.gap(4));

		final JButton manual = UiUtils.button("COMPLETE MANUALLY");
		manual.setToolTipText("Record a completion the plugin could not detect");
		manual.addActionListener(e -> doCompleteManually());
		buttons.add(manual);
		buttons.add(UiUtils.gap(4));

		final JButton reset = UiUtils.button("RESET ASSIGNMENT");
		reset.setToolTipText("Abandon without spending a skip. Does not count as a completion.");
		reset.addActionListener(e -> doReset());
		buttons.add(reset);

		return buttons;
	}

	private JPanel buildStats()
	{
		final RouletteSaveData data = assignmentService.getData();

		final JPanel section = UiUtils.section();
		section.add(UiUtils.title("PROGRESS"));
		section.add(UiUtils.gap(6));

		section.add(UiUtils.statRow("Assignments completed",
			UiUtils.valueLabel(Integer.toString(data.getCompletedCount()))));

		final JLabel streak = UiUtils.valueLabel(Integer.toString(data.getCurrentStreak()));
		if (data.getCurrentStreak() > 0)
		{
			streak.setForeground(UiUtils.SUCCESS);
		}
		section.add(UiUtils.statRow("Current streak", streak));
		section.add(UiUtils.statRow("Best streak", UiUtils.valueLabel(Integer.toString(data.getBestStreak()))));
		section.add(UiUtils.statRow("Slots earned here",
			UiUtils.valueLabel(Integer.toString(data.getUnlocksEarned()))));
		section.add(UiUtils.statRow("Skips available",
			UiUtils.valueLabel(Integer.toString(data.getAvailableSkips()))));
		section.add(UiUtils.statRow("Assignments skipped",
			UiUtils.valueLabel(Integer.toString(data.getTotalSkipped()))));

		// The account-wide figure straight from the game, for context.
		final int obtained = logStateService.getTotalObtained();
		final int max = logStateService.getTotalMax();
		final boolean synced = logStateService.areTotalsSynced();

		final JLabel accountTotal = UiUtils.valueLabel(synced ? obtained + " / " + max : "Not synced");
		if (!synced)
		{
			accountTotal.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			accountTotal.setToolTipText("Open your Collection Log in-game once to sync these totals.");
		}
		section.add(UiUtils.statRow("Account log slots", accountTotal));

		// Until the totals arrive, a page that reads "not complete" is genuinely
		// ambiguous, so say so rather than quietly filtering on a guess.
		if (!synced)
		{
			section.add(UiUtils.gap(6));
			section.add(warning("Open your Collection Log in-game once so the plugin can read which "
				+ "pages you have finished. Until then, completed pages may still be rolled."));
		}

		return section;
	}

	// ------------------------------------------------------------------
	// Actions
	// ------------------------------------------------------------------

	private void doRoll()
	{
		final RollResult result = assignmentService.roll();
		if (!result.isRolled())
		{
			JOptionPane.showMessageDialog(this, result.getMessage(),
				"Cannot roll", JOptionPane.WARNING_MESSAGE);
		}
	}

	private void doSkip()
	{
		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (activity == null)
		{
			return;
		}

		final JComboBox<SkipReason> reasons = new JComboBox<>(SkipReason.values());
		reasons.setSelectedItem(SkipReason.PERSONAL_CHOICE);

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.add(new JLabel("Skip " + activity.getDisplayName() + "?"));
		content.add(new JLabel(" "));
		content.add(new JLabel("Reason:"));
		content.add(reasons);

		final int choice = JOptionPane.showConfirmDialog(this, content, "Skip assignment",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);

		if (choice != JOptionPane.OK_OPTION)
		{
			return;
		}

		final SkipResult result = assignmentService.skip((SkipReason) reasons.getSelectedItem());
		if (!result.isSkipped())
		{
			JOptionPane.showMessageDialog(this, result.getMessage(),
				"Cannot skip", JOptionPane.WARNING_MESSAGE);
		}
	}

	/**
	 * Manual completion always asks first, and always records itself as manual —
	 * the history must never imply the plugin verified something it did not.
	 */
	private void doCompleteManually()
	{
		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (activity == null)
		{
			return;
		}

		final JTextField itemField = new JTextField(16);

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.add(new JLabel("Complete " + activity.getDisplayName() + " manually?"));
		content.add(new JLabel(" "));
		content.add(new JLabel("Which item did you unlock? (optional)"));
		content.add(itemField);
		content.add(new JLabel(" "));
		content.add(new JLabel("This will be recorded as manually verified."));

		final int choice = JOptionPane.showConfirmDialog(this, content, "Complete manually",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);

		if (choice != JOptionPane.OK_OPTION)
		{
			return;
		}

		assignmentService.completeManually(itemField.getText(), CollectionLogUnlock.UNKNOWN_ITEM_ID);
	}

	private void doReset()
	{
		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (activity == null)
		{
			return;
		}

		final int choice = JOptionPane.showConfirmDialog(this,
			"Reset " + activity.getDisplayName() + "?\n\n"
				+ "It will be recorded as reset. This does not count as a completion\n"
				+ "and does not spend a skip, but it does break your streak.",
			"Reset assignment", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);

		if (choice == JOptionPane.YES_OPTION)
		{
			assignmentService.resetCurrent();
		}
	}

	private static JLabel warning(String text)
	{
		final JLabel label = new JLabel("<html><body style='width:170px'>" + text + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(UiUtils.WARNING);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** Minimal escaping so item and activity names cannot break the HTML labels. */
	private static String escape(String text)
	{
		return text == null ? "" : text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.collectionlogroulette.ui;

import com.collectionlogroulette.model.AssignmentHistoryEntry;
import com.collectionlogroulette.model.AssignmentResult;
import com.collectionlogroulette.model.RouletteSaveData;
import com.collectionlogroulette.service.AssignmentService;
import com.google.gson.Gson;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.io.File;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JFileChooser;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.filechooser.FileNameExtensionFilter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Scrollable list of finished assignments, plus a JSON export.
 *
 * <p>Export is strictly user-initiated through a {@link JFileChooser} — the
 * plugin never writes files on its own.
 */
@Slf4j
public class HistoryPanel extends JPanel
{
	private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("d MMM yyyy, HH:mm");

	private final AssignmentService assignmentService;
	private final Gson gson;

	public HistoryPanel(AssignmentService assignmentService, Gson gson)
	{
		this.assignmentService = assignmentService;
		this.gson = gson;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
	}

	public void rebuild()
	{
		removeAll();

		final List<AssignmentHistoryEntry> history = assignmentService.getHistory();

		final JPanel header = UiUtils.section();
		header.add(UiUtils.title("HISTORY"));
		header.add(UiUtils.gap(4));
		header.add(UiUtils.body(history.size() + " of " + RouletteSaveData.MAX_HISTORY + " retained"));
		header.add(UiUtils.gap(8));

		final JButton export = UiUtils.button("EXPORT AS JSON");
		export.setEnabled(!history.isEmpty());
		export.addActionListener(e -> exportHistory(history));
		header.add(export);

		header.add(UiUtils.gap(4));
		final JButton clear = UiUtils.button("CLEAR HISTORY");
		clear.setEnabled(!history.isEmpty());
		clear.addActionListener(e -> confirmClear());
		header.add(clear);

		add(header);
		add(UiUtils.gap(6));

		if (history.isEmpty())
		{
			final JPanel empty = UiUtils.section();
			empty.add(UiUtils.body("No assignments yet."));
			add(empty);
		}
		else
		{
			for (AssignmentHistoryEntry entry : history)
			{
				add(buildEntry(entry));
				add(UiUtils.gap(4));
			}
		}

		revalidate();
		repaint();
	}

	private JPanel buildEntry(AssignmentHistoryEntry entry)
	{
		final JPanel panel = UiUtils.column();
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, resultColor(entry.getResult())),
			BorderFactory.createEmptyBorder(6, 6, 6, 6)));

		final JLabel name = new JLabel(entry.getActivityName());
		name.setFont(UiUtils.smallBold());
		name.setForeground(Color.WHITE);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(name);

		final JLabel result = new JLabel(describeResult(entry));
		result.setFont(FontManager.getRunescapeSmallFont());
		result.setForeground(resultColor(entry.getResult()));
		result.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(result);

		if (entry.hasUnlock())
		{
			final JLabel unlock = new JLabel("<html><body style='width:160px'>"
				+ escape(entry.getUnlockItemName()) + "</body></html>");
			unlock.setFont(FontManager.getRunescapeSmallFont());
			unlock.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			unlock.setAlignmentX(Component.LEFT_ALIGNMENT);
			panel.add(unlock);
		}

		panel.add(UiUtils.gap(2));

		final StringBuilder facts = new StringBuilder();
		facts.append(UiUtils.formatDuration(entry.getDurationMillis()));
		if (entry.getEstimatedLootValue() != 0)
		{
			facts.append("  ·  ").append(UiUtils.formatGp(entry.getEstimatedLootValue()));
		}
		if (entry.getKillCount() > 0)
		{
			facts.append("  ·  ").append(entry.getKillCount()).append(" kills");
		}

		final JLabel factsLabel = new JLabel(facts.toString());
		factsLabel.setFont(FontManager.getRunescapeSmallFont());
		factsLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		factsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(factsLabel);

		final JLabel when = new JLabel(DATE_FORMAT.format(new Date(entry.getEndTimeMillis())));
		when.setFont(FontManager.getRunescapeSmallFont());
		when.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		when.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(when);

		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	private static String describeResult(AssignmentHistoryEntry entry)
	{
		final AssignmentResult result = entry.getResult();
		if (result == null)
		{
			return "Unknown";
		}

		if (result == AssignmentResult.COMPLETED && entry.getVerification() != null)
		{
			return result.getDisplayName() + " · " + entry.getVerification().getDisplayName();
		}

		if (result == AssignmentResult.SKIPPED && entry.getSkipReason() != null)
		{
			return result.getDisplayName() + " · " + entry.getSkipReason().getDisplayName();
		}

		return result.getDisplayName();
	}

	private static Color resultColor(AssignmentResult result)
	{
		if (result == null)
		{
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}

		switch (result)
		{
			case COMPLETED:
				return UiUtils.SUCCESS;
			case SKIPPED:
				return UiUtils.WARNING;
			case RESET:
			default:
				return ColorScheme.MEDIUM_GRAY_COLOR;
		}
	}

	private void confirmClear()
	{
		final int choice = JOptionPane.showConfirmDialog(this,
			"Delete all stored assignment history?\n\nThis cannot be undone.",
			"Clear history", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);

		if (choice == JOptionPane.YES_OPTION)
		{
			assignmentService.clearHistory();
		}
	}

	/**
	 * Writes history to a file the user picks. Nothing is written anywhere else,
	 * and an existing file is only overwritten after an explicit confirmation.
	 */
	private void exportHistory(List<AssignmentHistoryEntry> history)
	{
		final JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Export assignment history");
		chooser.setSelectedFile(new File("collection-log-roulette-history.json"));
		chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));

		if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}

		File target = chooser.getSelectedFile();
		if (!target.getName().toLowerCase().endsWith(".json"))
		{
			target = new File(target.getParentFile(), target.getName() + ".json");
		}

		if (target.exists())
		{
			final int overwrite = JOptionPane.showConfirmDialog(this,
				target.getName() + " already exists. Overwrite it?",
				"Confirm overwrite", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);

			if (overwrite != JOptionPane.YES_OPTION)
			{
				return;
			}
		}

		try (Writer writer = Files.newBufferedWriter(target.toPath(), StandardCharsets.UTF_8))
		{
			gson.toJson(history, writer);
			JOptionPane.showMessageDialog(this,
				"Exported " + history.size() + " entries to\n" + target.getAbsolutePath(),
				"Export complete", JOptionPane.INFORMATION_MESSAGE);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to export assignment history", e);
			JOptionPane.showMessageDialog(this,
				"Could not write the file:\n" + e.getMessage(),
				"Export failed", JOptionPane.ERROR_MESSAGE);
		}
	}

	private static String escape(String text)
	{
		return text == null ? "" : text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.collectionlogroulette.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.concurrent.TimeUnit;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
