import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Small Swing helpers shared by the panels.
 *
 * <p>Everything here sticks to plain Swing plus RuneLite's own {@link
 * ColorScheme} and {@link FontManager}, so the plugin inherits the client's look
 * instead of introducing a second visual language.
 */
public final class UiUtils
{
	/** Success green, matching the client's own "complete" colour. */
	public static final Color SUCCESS = ColorScheme.PROGRESS_COMPLETE_COLOR;

	/** Muted amber used for states the plugin could not verify. */
	public static final Color WARNING = ColorScheme.PROGRESS_INPROGRESS_COLOR;

	public static final Color ERROR = ColorScheme.PROGRESS_ERROR_COLOR;

	private UiUtils()
	{
	}

	public static JPanel column()
	{
		final JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	public static JPanel section()
	{
		final JPanel panel = column();
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		return panel;
	}

	public static JLabel title(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	public static JLabel body(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A "Label: value" row where the label is muted and the value stands out.
	 * Wrapped so long values push the label rather than clipping.
	 */
	public static JPanel statRow(String name, JLabel valueLabel)
	{
		final JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));

		final JLabel key = new JLabel(name);
		key.setFont(FontManager.getRunescapeSmallFont());
		key.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		row.add(key);
		row.add(Box.createHorizontalGlue());
		row.add(valueLabel);

		// Rows must not grow vertically when the panel has spare height.
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height + 4));
		return row;
	}

	public static JLabel valueLabel(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.WHITE);
		return label;
	}

	public static JButton button(String text)
	{
		final JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		button.setForeground(Color.WHITE);
		button.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		return button;
	}

	public static JButton primaryButton(String text)
	{
		final JButton button = button(text);
		button.setBackground(ColorScheme.BRAND_ORANGE);
		button.setForeground(Color.BLACK);
		button.setFont(FontManager.getRunescapeBoldFont());
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		return button;
	}

	public static Component gap(int height)
	{
		return Box.createRigidArea(new Dimension(0, height));
	}

	/** Formats a duration as HH:MM:SS. */
	public static String formatDuration(long millis)
	{
		if (millis < 0)
		{
			millis = 0;
		}

		final long hours = TimeUnit.MILLISECONDS.toHours(millis);
		final long minutes = TimeUnit.MILLISECONDS.toMinutes(millis) % 60;
		final long seconds = TimeUnit.MILLISECONDS.toSeconds(millis) % 60;

		return String.format("%02d:%02d:%02d", hours, minutes, seconds);
	}

	/** Formats a gp amount using the client's own short-stack notation. */
	public static String formatGp(long value)
	{
		if (value < 0)
		{
			return "-" + QuantityFormatter.quantityToRSDecimalStack((int) Math.min(-value, Integer.MAX_VALUE));
		}

		if (value <= Integer.MAX_VALUE)
		{
			return QuantityFormatter.quantityToRSDecimalStack((int) value);
		}

		return QuantityFormatter.quantityToStackSize(value);
	}

	public static Font smallBold()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 12f);
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.CollectionLogRouletteConfig;
import com.collectionlogroulette.model.ActivityType;
import com.collectionlogroulette.model.DifficultyTier;
import com.collectionlogroulette.model.RouletteActivity;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Decides which catalog activities may currently be rolled.
 *
 * <p>The completion lookup is passed in as a function rather than as a service
 * dependency so this class stays free of client access and is trivially
 * testable.
 */
@Singleton
public class ActivityEligibilityService
{
	private final CollectionLogRouletteConfig config;

	@Inject
	public ActivityEligibilityService(CollectionLogRouletteConfig config)
	{
		this.config = config;
	}

	/**
	 * @param all             the whole catalog
	 * @param excludedIds     activity ids the player has excluded in the panel
	 * @param completionState resolves an activity to what we know about its page
	 */
	public List<RouletteActivity> filterEligible(
		List<RouletteActivity> all,
		Set<String> excludedIds,
		Function<RouletteActivity, CompletionState> completionState)
	{
		final DifficultyTier min = config.minDifficulty();
		final DifficultyTier max = config.maxDifficulty();
		// A user who inverts the range should get the range they described, not
		// an empty pool.
		final DifficultyTier low = min.ordinal() <= max.ordinal() ? min : max;
		final DifficultyTier high = min.ordinal() <= max.ordinal() ? max : min;

		final List<RouletteActivity> eligible = new ArrayList<>();
		for (RouletteActivity activity : all)
		{
			if (excludedIds.contains(activity.getId()))
			{
				continue;
			}

			if (!isTypeEnabled(activity.getType()))
			{
				continue;
			}

			if (!activity.getDifficulty().isWithin(low, high))
			{
				continue;
			}

			if (!config.includeUnmetPrerequisites() && activity.getPrerequisiteNote() != null)
			{
				continue;
			}

			final CompletionState state = completionState.apply(activity);
			if (state == CompletionState.COMPLETE)
			{
				// Every slot is already obtained; there is nothing left to win here.
				continue;
			}

			if (state == CompletionState.UNKNOWN && !config.allowUnknownCompletion())
			{
				continue;
			}

			eligible.add(activity);
		}

		return eligible;
	}

	public boolean isTypeEnabled(ActivityType type)
	{
		switch (type)
		{
			case BOSS:
				return config.enableBosses();
			case RAID:
				return config.enableRaids();
			case MINIGAME:
				return config.enableMinigames();
			case CLUE:
				return config.enableClues();
			case SKILLING:
				return config.enableSkilling();
			case OTHER:
			default:
				return config.enableOther();
		}
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.CollectionLogRouletteConfig;
import com.collectionlogroulette.model.Assignment;
import com.collectionlogroulette.model.AssignmentHistoryEntry;
import com.collectionlogroulette.model.AssignmentResult;
import com.collectionlogroulette.model.AssignmentState;
import com.collectionlogroulette.model.CollectionLogUnlock;
import com.collectionlogroulette.model.LootEntry;
import com.collectionlogroulette.model.RouletteActivity;
import com.collectionlogroulette.model.RouletteSaveData;
import com.collectionlogroulette.model.SkipReason;
import com.collectionlogroulette.model.VerificationMethod;
import com.collectionlogroulette.model.WeightCategory;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.Function;
import java.util.function.LongSupplier;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The assignment state machine and the single owner of mutable roulette state.
 *
 * <p>Everything that changes progress goes through here: the panel, the overlay
 * and the plugin's event subscribers all read and mutate state via this class
 * rather than touching {@link RouletteSaveData} directly. That keeps the
 * "never award two completions for one assignment" and "never overwrite an
 * active assignment" rules in one place.
 *
 * <p>Not thread safe by design — every entry point is called from either the
 * client thread or the Swing EDT, and the plugin marshals between them.
 */
@Slf4j
@Singleton
public class AssignmentService
{
	private final ActivityCatalog catalog;
	private final AssignmentSelectionService selectionService;
	private final ActivityEligibilityService eligibilityService;
	private final PersistenceService persistenceService;
	private final CollectionLogRouletteConfig config;
	private final LongSupplier clock;

	private final List<Runnable> changeListeners = new ArrayList<>();

	/**
	 * Fired exactly once per completion, so the plugin can raise a notification
	 * without having to diff state on every generic change event.
	 */
	private final List<BiConsumer<RouletteActivity, CollectionLogUnlock>> completionListeners = new ArrayList<>();

	private RouletteSaveData data = new RouletteSaveData();

	/**
	 * Supplies what the plugin knows about each activity's log page. Replaced by
	 * the plugin at start-up with a client-backed lookup; defaults to "unknown"
	 * so the service works standalone in tests.
	 */
	private Function<RouletteActivity, CompletionState> completionLookup = a -> CompletionState.UNKNOWN;

	@Inject
	public AssignmentService(
		ActivityCatalog catalog,
		AssignmentSelectionService selectionService,
		ActivityEligibilityService eligibilityService,
		PersistenceService persistenceService,
		CollectionLogRouletteConfig config)
	{
		this(catalog, selectionService, eligibilityService, persistenceService, config,
			System::currentTimeMillis);
	}

	public AssignmentService(
		ActivityCatalog catalog,
		AssignmentSelectionService selectionService,
		ActivityEligibilityService eligibilityService,
		PersistenceService persistenceService,
		CollectionLogRouletteConfig config,
		LongSupplier clock)
	{
		this.catalog = catalog;
		this.selectionService = selectionService;
		this.eligibilityService = eligibilityService;
		this.persistenceService = persistenceService;
		this.config = config;
		this.clock = clock;
	}

	// ------------------------------------------------------------------
	// Wiring
	// ------------------------------------------------------------------

	public void setCompletionLookup(Function<RouletteActivity, CompletionState> lookup)
	{
		this.completionLookup = lookup == null ? a -> CompletionState.UNKNOWN : lookup;
	}

	public void addChangeListener(Runnable listener)
	{
		changeListeners.add(listener);
	}

	public void addCompletionListener(BiConsumer<RouletteActivity, CollectionLogUnlock> listener)
	{
		completionListeners.add(listener);
	}

	public void clearChangeListeners()
	{
		changeListeners.clear();
		completionListeners.clear();
	}

	private void fireChanged()
	{
		for (Runnable listener : changeListeners)
		{
			try
			{
				listener.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Collection Log Roulette listener failed", e);
			}
		}
	}

	// ------------------------------------------------------------------
	// Load / save
	// ------------------------------------------------------------------

	/**
	 * Loads the active profile's data and resumes the clock if appropriate.
	 * Safe to call repeatedly; used on start-up and on account switch.
	 */
	public void loadForCurrentProfile()
	{
		data = persistenceService.load();

		applyCatalogDefaults();
		discardAssignmentForUnknownActivity();

		// Time never accrues while the plugin is not watching. Any interval left
		// open by the previous session is discarded rather than banked, because
		// its end time is unknowable — saves checkpoint the clock precisely so
		// that only the last few seconds before an unclean exit are lost.
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment != null)
		{
			assignment.discardOpenInterval();
		}

		log.debug("Loaded roulette data: {} completed, streak {}, assignment {}",
			data.getCompletedCount(), data.getCurrentStreak(),
			assignment == null ? "none" : assignment.getActivityId());

		fireChanged();
	}

	/**
	 * Drops a restored assignment whose activity no longer exists in the catalog.
	 *
	 * <p>Otherwise the plugin soft-locks: the state stays {@code ACTIVE} so Roll
	 * is refused, but the panel cannot render an activity it has no definition
	 * for, so it falls back to the idle view — leaving no visible way out. This
	 * happens whenever an activity id is retired or renamed between versions.
	 */
	private void discardAssignmentForUnknownActivity()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || catalog.getById(assignment.getActivityId()) != null)
		{
			return;
		}

		log.warn("Discarding saved assignment for unknown activity '{}' — it is not in this "
			+ "build's catalog. Progress counters and history are unaffected.",
			assignment.getActivityId());

		data.setCurrentAssignment(null);
	}

	/**
	 * Seeds a fresh profile's exclusions from the catalog's {@code
	 * enabledByDefault} flags. Runs exactly once per profile so it can never
	 * clobber choices the player has since made.
	 */
	private void applyCatalogDefaults()
	{
		if (data.isDefaultsApplied())
		{
			return;
		}

		data.setDefaultsApplied(true);

		for (RouletteActivity activity : catalog.getActivities())
		{
			if (!activity.isEnabledByDefault())
			{
				data.getExcludedActivityIds().add(activity.getId());
			}
		}
	}

	public void save()
	{
		// Bank whatever has elapsed so far so the stored total is accurate even if
		// the client never gets to shut down cleanly.
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment != null)
		{
			assignment.checkpointTimer(now());
		}

		persistenceService.save(data);
	}

	/** Drops in-memory state without touching what is on disk. */
	public void unload()
	{
		data = new RouletteSaveData();
		fireChanged();
	}

	public RouletteSaveData getData()
	{
		return data;
	}

	// ------------------------------------------------------------------
	// Queries
	// ------------------------------------------------------------------

	@Nullable
	public Assignment getCurrentAssignment()
	{
		return data.getCurrentAssignment();
	}

	public AssignmentState getState()
	{
		final Assignment assignment = data.getCurrentAssignment();
		return assignment == null ? AssignmentState.NONE : assignment.getState();
	}

	@Nullable
	public RouletteActivity getCurrentActivity()
	{
		final Assignment assignment = data.getCurrentAssignment();
		return assignment == null ? null : catalog.getById(assignment.getActivityId());
	}

	public List<RouletteActivity> getEligibleActivities()
	{
		return eligibilityService.filterEligible(
			catalog.getActivities(), data.getExcludedActivityIds(), completionLookup);
	}

	public CompletionState getCompletionState(RouletteActivity activity)
	{
		return completionLookup.apply(activity);
	}

	public long getElapsedMillis()
	{
		final Assignment assignment = data.getCurrentAssignment();
		return assignment == null ? 0L : assignment.getElapsedMillis(now());
	}

	public boolean canSkip()
	{
		switch (config.skipMode())
		{
			case UNLIMITED:
				return true;
			case NONE:
				return false;
			case EARNED:
			default:
				return data.getAvailableSkips() > 0;
		}
	}

	public boolean isExcluded(String activityId)
	{
		return data.getExcludedActivityIds().contains(activityId);
	}

	/**
	 * @return whether a RuneScape account is logged in, and therefore whether
	 * progress can actually be stored
	 */
	public boolean isPersistenceAvailable()
	{
		return persistenceService.isProfileAvailable();
	}

	// ------------------------------------------------------------------
	// Commands
	// ------------------------------------------------------------------

	/**
	 * Rolls a new assignment.
	 *
	 * <p>Refuses while an assignment is {@link AssignmentState#ACTIVE} — the Roll
	 * button must never silently discard work in progress. Rolling over a
	 * {@code COMPLETED} assignment is fine because its result is already in
	 * history.
	 */
	public RollResult roll()
	{
		final Assignment current = data.getCurrentAssignment();
		if (current != null && current.isActive())
		{
			return RollResult.blocked();
		}

		// Without a profile there is nowhere to save to, so the assignment would
		// look real until login replaced it with the account's actual state.
		if (!isPersistenceAvailable())
		{
			return RollResult.noProfile();
		}

		final List<RouletteActivity> eligible = getEligibleActivities();
		final Optional<RouletteActivity> chosen = selectionService.select(
			eligible,
			data.getPreviousActivityId(),
			config.selectionMode(),
			buildWeights(),
			config.avoidImmediateRepeat());

		if (!chosen.isPresent())
		{
			log.debug("Roll requested but no activity is eligible ({} in catalog)", catalog.size());
			return RollResult.noneEligible();
		}

		final RouletteActivity activity = chosen.get();
		data.setCurrentAssignment(new Assignment(activity.getId(), now()));
		data.setPreviousActivityId(activity.getId());

		log.info("Collection Log Roulette assigned '{}' ({} eligible)", activity.getId(), eligible.size());

		save();
		fireChanged();
		return RollResult.rolled(activity);
	}

	public SkipResult skip(@Nullable SkipReason reason)
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive())
		{
			return SkipResult.noActive();
		}

		if (config.skipMode() == SkipMode.NONE)
		{
			return SkipResult.disabled();
		}

		if (config.skipMode() == SkipMode.EARNED && data.getAvailableSkips() <= 0)
		{
			return SkipResult.unavailable();
		}

		if (config.skipMode() == SkipMode.EARNED)
		{
			data.setAvailableSkips(data.getAvailableSkips() - 1);
		}

		final RouletteActivity activity = catalog.getById(assignment.getActivityId());
		final String name = activity == null ? assignment.getActivityId() : activity.getDisplayName();

		finish(assignment, AssignmentResult.SKIPPED, VerificationMethod.NONE, reason);

		// A skip breaks the streak but must not touch the completion, unlock or
		// streak-best counters.
		data.setTotalSkipped(data.getTotalSkipped() + 1);
		data.setCurrentStreak(0);
		data.setCurrentAssignment(null);

		log.info("Collection Log Roulette skipped '{}' (reason: {})", assignment.getActivityId(), reason);

		save();
		fireChanged();
		return SkipResult.skipped(name);
	}

	/**
	 * Abandons the current assignment without spending a skip and without
	 * counting it as a completion. Recorded in history as {@link
	 * AssignmentResult#RESET} so the time spent is not simply lost.
	 */
	public boolean resetCurrent()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null)
		{
			return false;
		}

		if (assignment.isActive())
		{
			finish(assignment, AssignmentResult.RESET, VerificationMethod.NONE, null);
			data.setCurrentStreak(0);
		}

		data.setCurrentAssignment(null);

		log.debug("Reset assignment '{}'", assignment.getActivityId());

		save();
		fireChanged();
		return true;
	}

	/**
	 * Offers a detected unlock to the active assignment.
	 *
	 * <p>An unlock only completes the assignment when it is in the assigned
	 * activity's verified item set. Anything else either belongs to a different
	 * catalog activity ({@link UnlockOutcome#UNRELATED}) or cannot be attributed
	 * at all ({@link UnlockOutcome#NEEDS_CONFIRMATION}) — in neither case does
	 * the plugin complete the assignment on its own.
	 */
	public UnlockOutcome offerUnlock(CollectionLogUnlock unlock)
	{
		if (unlock == null)
		{
			return UnlockOutcome.IGNORED;
		}

		// Always remember what we saw, even if it does not help right now — this
		// is the plugin's own local cache of observed unlocks.
		if (unlock.hasItemId())
		{
			data.getObservedUnlockItemIds().add(unlock.getItemId());
		}

		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive())
		{
			save();
			return UnlockOutcome.IGNORED;
		}

		final RouletteActivity activity = catalog.getById(assignment.getActivityId());
		if (activity == null)
		{
			log.warn("Active assignment references unknown activity '{}'", assignment.getActivityId());
			return UnlockOutcome.IGNORED;
		}

		if (unlock.hasItemId() && activity.containsItem(unlock.getItemId()))
		{
			completeInternal(assignment, activity, unlock, VerificationMethod.AUTOMATIC);
			return UnlockOutcome.COMPLETED;
		}

		if (unlock.hasItemId() && !catalog.findByItemId(unlock.getItemId()).isEmpty())
		{
			// The item is mapped, just not to this activity. No prompt needed.
			log.debug("Unlock '{}' ({}) belongs to another activity, not '{}'",
				unlock.getItemName(), unlock.getItemId(), activity.getId());
			return UnlockOutcome.UNRELATED;
		}

		log.debug("Could not attribute unlock '{}' (id {}) to assignment '{}': {}",
			unlock.getItemName(), unlock.getItemId(), activity.getId(),
			unlock.hasItemId()
				? "item id is not in any catalog activity"
				: "item name could not be resolved to an id");

		assignment.setPendingUnlock(unlock);
		save();
		fireChanged();
		return UnlockOutcome.NEEDS_CONFIRMATION;
	}

	/**
	 * Accepts a pending unlock the player confirmed belongs to the assignment.
	 * Recorded as manual, because the plugin did not verify it.
	 */
	public boolean confirmPendingUnlock()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive() || assignment.getPendingUnlock() == null)
		{
			return false;
		}

		final RouletteActivity activity = catalog.getById(assignment.getActivityId());
		if (activity == null)
		{
			return false;
		}

		final CollectionLogUnlock unlock = assignment.getPendingUnlock();
		assignment.setPendingUnlock(null);
		completeInternal(assignment, activity, unlock, VerificationMethod.MANUAL);
		return true;
	}

	public void dismissPendingUnlock()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || assignment.getPendingUnlock() == null)
		{
			return;
		}

		assignment.setPendingUnlock(null);
		save();
		fireChanged();
	}

	/**
	 * Player-declared completion. Always recorded as {@link
	 * VerificationMethod#MANUAL} so history stays honest about what was checked.
	 */
	public boolean completeManually(@Nullable String itemName, int itemId)
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive())
		{
			return false;
		}

		final RouletteActivity activity = catalog.getById(assignment.getActivityId());
		if (activity == null)
		{
			return false;
		}

		final String name = itemName == null || itemName.trim().isEmpty()
			? "Unspecified item"
			: itemName.trim();

		final CollectionLogUnlock unlock = new CollectionLogUnlock(name, itemId, now());
		assignment.setPendingUnlock(null);
		completeInternal(assignment, activity, unlock, VerificationMethod.MANUAL);
		return true;
	}

	/**
	 * The single path that turns an active assignment into a completed one.
	 * Guarded on {@link AssignmentState#ACTIVE}, which is what makes double
	 * completion impossible regardless of how many events arrive.
	 */
	private void completeInternal(Assignment assignment, RouletteActivity activity,
		CollectionLogUnlock unlock, VerificationMethod verification)
	{
		if (!assignment.isActive())
		{
			log.debug("Ignoring completion for '{}' — assignment is already {}",
				activity.getId(), assignment.getState());
			return;
		}

		assignment.setUnlock(unlock);
		assignment.setVerification(verification);

		finish(assignment, AssignmentResult.COMPLETED, verification, null);
		assignment.setState(AssignmentState.COMPLETED);

		data.setCompletedCount(data.getCompletedCount() + 1);
		data.setUnlocksEarned(data.getUnlocksEarned() + 1);
		data.setCurrentStreak(data.getCurrentStreak() + 1);
		data.setBestStreak(Math.max(data.getBestStreak(), data.getCurrentStreak()));

		if (unlock.hasItemId())
		{
			data.getObservedUnlockItemIds().add(unlock.getItemId());
		}

		awardSkipIfEarned();

		log.info("Collection Log Roulette completed '{}' with '{}' ({})",
			activity.getId(), unlock.getItemName(), verification);

		save();
		fireChanged();

		for (BiConsumer<RouletteActivity, CollectionLogUnlock> listener : completionListeners)
		{
			try
			{
				listener.accept(activity, unlock);
			}
			catch (RuntimeException e)
			{
				log.warn("Collection Log Roulette completion listener failed", e);
			}
		}
	}

	private void awardSkipIfEarned()
	{
		if (config.skipMode() != SkipMode.EARNED)
		{
			return;
		}

		final int perSkip = Math.max(1, config.completionsPerSkip());
		int progress = data.getCompletionsTowardsNextSkip() + 1;

		while (progress >= perSkip)
		{
			progress -= perSkip;
			data.setAvailableSkips(data.getAvailableSkips() + 1);
			log.debug("Earned a skip; {} now available", data.getAvailableSkips());
		}

		data.setCompletionsTowardsNextSkip(progress);
	}

	/**
	 * Stops the clock and appends the history entry. Shared by completion, skip
	 * and reset so all three record duration and loot the same way.
	 */
	private void finish(Assignment assignment, AssignmentResult result,
		VerificationMethod verification, @Nullable SkipReason skipReason)
	{
		final long nowMillis = now();
		assignment.pauseTimer(nowMillis);
		assignment.setEndedAtMillis(nowMillis);

		final RouletteActivity activity = catalog.getById(assignment.getActivityId());
		final CollectionLogUnlock unlock = assignment.getUnlock();

		data.addHistoryEntry(AssignmentHistoryEntry.builder()
			.activityId(assignment.getActivityId())
			.activityName(activity == null ? assignment.getActivityId() : activity.getDisplayName())
			.startTimeMillis(assignment.getStartedAtMillis())
			.endTimeMillis(nowMillis)
			.durationMillis(assignment.getAccumulatedMillis())
			.result(result)
			.unlockItemId(unlock == null ? CollectionLogUnlock.UNKNOWN_ITEM_ID : unlock.getItemId())
			.unlockItemName(unlock == null ? null : unlock.getItemName())
			.estimatedLootValue(assignment.getTotalLootValue())
			.killCount(assignment.getKillCount())
			.verification(verification)
			.skipReason(skipReason)
			.build());
	}

	// ------------------------------------------------------------------
	// Tracking hooks
	// ------------------------------------------------------------------

	/** Records loot. No-op unless an assignment is actively running. */
	public void recordLoot(int itemId, int quantity, int gePerItem, String source)
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive() || quantity <= 0)
		{
			return;
		}

		assignment.getLoot().add(new LootEntry(itemId, quantity, gePerItem, source, now()));
	}

	/** Increments the kill counter. No-op unless an assignment is running. */
	public void recordKill()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive())
		{
			return;
		}

		assignment.setKillCount(assignment.getKillCount() + 1);
	}

	public void pauseTimer()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isTimerRunning())
		{
			return;
		}

		assignment.pauseTimer(now());
		save();
		fireChanged();
	}

	public void resumeTimer()
	{
		final Assignment assignment = data.getCurrentAssignment();
		if (assignment == null || !assignment.isActive() || assignment.isTimerRunning())
		{
			return;
		}

		assignment.resumeTimer(now());
		fireChanged();
	}

	// ------------------------------------------------------------------
	// Exclusions
	// ------------------------------------------------------------------

	public void setExcluded(String activityId, boolean excluded)
	{
		final Set<String> excludedIds = data.getExcludedActivityIds();
		final boolean changed = excluded ? excludedIds.add(activityId) : excludedIds.remove(activityId);

		if (changed)
		{
			save();
			fireChanged();
		}
	}

	/**
	 * Applies one exclusion state to many activities at once.
	 *
	 * <p>Exists so the panel's "enable/disable all" buttons produce a single save
	 * and a single UI rebuild instead of one per activity.
	 */
	public void setExcluded(Collection<String> activityIds, boolean excluded)
	{
		final Set<String> excludedIds = data.getExcludedActivityIds();
		boolean changed = false;

		for (String activityId : activityIds)
		{
			changed |= excluded ? excludedIds.add(activityId) : excludedIds.remove(activityId);
		}

		if (changed)
		{
			save();
			fireChanged();
		}
	}

	public List<AssignmentHistoryEntry> getHistory()
	{
		return Collections.unmodifiableList(data.getHistory());
	}

	public void clearHistory()
	{
		data.getHistory().clear();
		save();
		fireChanged();
	}

	private Map<WeightCategory, Integer> buildWeights()
	{
		final Map<WeightCategory, Integer> weights = new EnumMap<>(WeightCategory.class);
		weights.put(WeightCategory.BOSS_RAID, config.weightBossRaid());
		weights.put(WeightCategory.MINIGAME, config.weightMinigame());
		weights.put(WeightCategory.CLUE, config.weightClue());
		weights.put(WeightCategory.OTHER, config.weightOther());
		return weights;
	}

	private long now()
	{
		return clock.getAsLong();
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.CollectionLogTab;
import com.collectionlogroulette.model.RouletteActivity;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Mirrors the game's own Collection Log bookkeeping.
 *
 * <p>OSRS exposes, per account:
 * <ul>
 *     <li>{@code COLLECTION_*_COMPLETED} varbits — set once every slot on a
 *     given log page has been obtained.</li>
 *     <li>{@code COLLECTION_COUNT} / {@code COLLECTION_COUNT_MAX} varps — total
 *     slots obtained and the maximum.</li>
 *     <li>Per-tab {@code COLLECTION_COUNT_*} varps.</li>
 * </ul>
 *
 * <p>That is enough to answer "is this page already finished?" authoritatively,
 * which is what drives eligibility. It is <b>not</b> enough to enumerate which
 * individual items are owned, so the plugin never claims to know that.
 *
 * <h2>Threading</h2>
 * {@link #refresh()} must run on the client thread. The cached results live in
 * concurrent maps and are read from the Swing EDT and the client thread alike.
 */
@Slf4j
@Singleton
public class CollectionLogStateService
{
	private final Client client;

	/** activity id -> whether the game says its page is fully obtained. */
	private final Map<String, Boolean> pageCompleted = new ConcurrentHashMap<>();

	/**
	 * Snapshot of per-tab obtained counts. Read and cached but not yet consulted
	 * for completion decisions — see the class javadoc.
	 */
	private final Map<CollectionLogTab, Integer> tabCounts = new ConcurrentHashMap<>();

	/** Varbits worth reacting to, precomputed by {@link #initTrackedVarbits}. */
	private volatile Set<Integer> trackedVarbits = Collections.emptySet();

	private volatile int totalObtained = -1;
	private volatile int totalMax = -1;

	/** Whether varbits have been read at all (i.e. we are logged in). */
	private volatile boolean stateKnown;

	/**
	 * Whether the server has delivered the slot totals. Doubles as the evidence
	 * that a zero completion varbit really means "not finished".
	 */
	private volatile boolean totalsSynced;

	@Inject
	public CollectionLogStateService(Client client)
	{
		this.client = client;
	}

	/**
	 * Re-reads every tracked varbit and varp.
	 *
	 * <p>Must be called on the client thread. Cheap enough to run on login and
	 * whenever a relevant varbit changes; it is not called per tick.
	 */
	public void refresh(Iterable<RouletteActivity> activities)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final Map<String, Boolean> completed = new HashMap<>();
		for (RouletteActivity activity : activities)
		{
			if (!activity.hasCompletionVarbit())
			{
				continue;
			}

			completed.put(activity.getId(), client.getVarbitValue(activity.getCompletionVarbitId()) == 1);
		}

		pageCompleted.clear();
		pageCompleted.putAll(completed);

		final Map<CollectionLogTab, Integer> counts = new EnumMap<>(CollectionLogTab.class);
		for (CollectionLogTab tab : CollectionLogTab.values())
		{
			counts.put(tab, client.getVarpValue(tab.getObtainedVarpId()));
		}

		tabCounts.clear();
		tabCounts.putAll(counts);

		totalObtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		totalMax = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);

		// The slot totals are not pushed at login; they arrive once the player
		// opens the Collection Log interface. COLLECTION_COUNT_MAX is the tell —
		// it is a constant of the game and never legitimately 0, so a zero means
		// "not delivered yet" rather than "no progress".
		//
		// The per-page COMPLETED varbits are a separate matter: they are part of
		// the account's varbit set and are available immediately. See
		// getCompletionState for how the two are combined.
		totalsSynced = totalMax > 0;
		stateKnown = true;

		log.debug("Collection log state refreshed: {} pages tracked, totals {}",
			pageCompleted.size(),
			totalsSynced ? (totalObtained + "/" + totalMax) : "not synced yet");
	}

	/**
	 * Clears everything. Called on logout and account switch so one account's
	 * completion flags never leak into another's eligibility check.
	 */
	public void clear()
	{
		pageCompleted.clear();
		tabCounts.clear();
		totalObtained = -1;
		totalMax = -1;
		stateKnown = false;
		totalsSynced = false;
	}

	/** Whether the account-wide slot totals have been delivered by the server. */
	public boolean areTotalsSynced()
	{
		return totalsSynced;
	}

	/**
	 * Builds the set of varbits worth reacting to.
	 *
	 * <p>Called once at start-up. {@code VarbitChanged} fires many times per tick
	 * for varbits that have nothing to do with this plugin, so the hot path has to
	 * be a set lookup rather than a scan of the catalog.
	 */
	public void initTrackedVarbits(Iterable<RouletteActivity> activities)
	{
		final Set<Integer> tracked = new HashSet<>();
		tracked.add(VarbitID.OPTION_COLLECTION_NEW_ITEM);

		for (RouletteActivity activity : activities)
		{
			if (activity.hasCompletionVarbit())
			{
				tracked.add(activity.getCompletionVarbitId());
			}
		}

		trackedVarbits = Collections.unmodifiableSet(tracked);
	}

	/**
	 * @return whether a change to this varbit should trigger a refresh
	 */
	public boolean isTrackedVarbit(int varbitId)
	{
		return trackedVarbits.contains(varbitId);
	}

	/**
	 * @return whether a change to this varp should trigger a refresh
	 *
	 * <p>The slot totals arrive as varp updates when the player opens the
	 * Collection Log. Watching for them is what lets page state upgrade from
	 * unknown to known mid-session without polling.
	 */
	public boolean isTrackedVarp(int varpId)
	{
		return varpId == VarPlayerID.COLLECTION_COUNT || varpId == VarPlayerID.COLLECTION_COUNT_MAX;
	}

	/**
	 * What the plugin knows about this activity's log page.
	 *
	 * <p>The asymmetry here is deliberate. An unpopulated varbit reads 0, so:
	 * <ul>
	 *     <li>a <b>1</b> can only have come from the server — {@link
	 *     CompletionState#COMPLETE} is always trustworthy;</li>
	 *     <li>a <b>0</b> is ambiguous — it means "not finished" only once we have
	 *     independent evidence the data arrived. Without that, reporting
	 *     INCOMPLETE would be claiming knowledge we do not have, so it degrades
	 *     to {@link CompletionState#UNKNOWN}.</li>
	 * </ul>
	 * The slot totals are used as that independent evidence.
	 */
	public CompletionState getCompletionState(RouletteActivity activity)
	{
		if (!stateKnown || !activity.hasCompletionVarbit())
		{
			return CompletionState.UNKNOWN;
		}

		final Boolean completed = pageCompleted.get(activity.getId());
		if (completed == null)
		{
			return CompletionState.UNKNOWN;
		}

		if (completed)
		{
			return CompletionState.COMPLETE;
		}

		return totalsSynced ? CompletionState.INCOMPLETE : CompletionState.UNKNOWN;
	}

	/**
	 * Total collection log slots the account has obtained, or -1 until the server
	 * has actually delivered the figure. A raw 0 here would read as "no progress"
	 * when it really means "not sent yet".
	 */
	public int getTotalObtained()
	{
		return totalsSynced ? totalObtained : -1;
	}

	/** Maximum obtainable slots, or -1 until the server has delivered it. */
	public int getTotalMax()
	{
		return totalsSynced ? totalMax : -1;
	}

	public boolean isStateKnown()
	{
		return stateKnown;
	}

	/**
	 * Reads the in-game "new collection log item" announcement setting.
	 *
	 * <p>Zero means the player turned the announcement off entirely, which is the
	 * one case where automatic detection genuinely cannot work — worth telling
	 * the player about rather than silently never completing anything.
	 *
	 * <p>Must be called on the client thread.
	 */
	public boolean isAnnouncementEnabled()
	{
		return getAnnouncementSetting() != 0;
	}

	/**
	 * Raw value of the in-game "Collection log - New item" setting, or -1 when
	 * not logged in.
	 *
	 * <p>Exposed separately from {@link #isAnnouncementEnabled()} so the actual
	 * value can be logged. A plain "disabled" message is ambiguous between "the
	 * player turned it off" and "the varbit had not been delivered when we
	 * looked", and those need very different responses.
	 */
	public int getAnnouncementSetting()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return -1;
		}

		return client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM);
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.CollectionLogUnlock;
import java.util.Optional;

/**
 * Turns raw game text into a {@link CollectionLogUnlock}.
 *
 * <p>Kept as an interface, and kept strictly separate from anything that decides
 * whether an assignment is complete, so the parsing can be unit tested against
 * representative messages without a client.
 */
public interface CollectionLogDetectionService
{
	/**
	 * @param rawText         game text, possibly containing Jagex colour tags
	 * @param timestampMillis when the text was observed
	 * @return the unlock, or empty when the text is not a collection log
	 * notification or is a duplicate of one already reported
	 */
	Optional<CollectionLogUnlock> detectUnlock(String rawText, long timestampMillis);

	/**
	 * Reports an unlock sourced from the pop-up notification path, where the item
	 * name arrives already separated from the "Collection log" title.
	 */
	Optional<CollectionLogUnlock> detectUnlockFromNotification(String title, String body, long timestampMillis);

	/** Clears duplicate-suppression state, e.g. on logout or account switch. */
	void reset();
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.RouletteActivity;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Outcome of pressing Roll, including why a roll was refused.
 */
@Value
public class RollResult
{
	public enum Status
	{
		ROLLED,
		/** An assignment is already active; it must be finished, skipped or reset. */
		BLOCKED_ACTIVE,
		/** Nothing passed the eligibility filters. */
		NO_ELIGIBLE_ACTIVITIES,

		/**
		 * No RuneScape account is logged in, so there is nowhere to persist the
		 * assignment to. Rolling anyway would look fine until login silently
		 * replaced it with the account's real saved state.
		 */
		NO_PROFILE
	}

	Status status;

	@Nullable
	RouletteActivity activity;

	String message;

	public boolean isRolled()
	{
		return status == Status.ROLLED;
	}

	static RollResult rolled(RouletteActivity activity)
	{
		return new RollResult(Status.ROLLED, activity, "Rolled " + activity.getDisplayName());
	}

	static RollResult blocked()
	{
		return new RollResult(Status.BLOCKED_ACTIVE, null,
			"Finish, skip or reset the current assignment before rolling again.");
	}

	static RollResult noneEligible()
	{
		return new RollResult(Status.NO_ELIGIBLE_ACTIVITIES, null,
			"No eligible activities. Check the content filters and the activity list.");
	}

	static RollResult noProfile()
	{
		return new RollResult(Status.NO_PROFILE, null,
			"Log in to a RuneScape account first — progress is stored per account.");
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.Assignment;
import com.collectionlogroulette.model.RouletteActivity;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Counts kills that belong to the current assignment.
 *
 * <p>Only activities that declare NPC ids get a counter. For clues, raids and
 * most minigames there is no supported per-completion signal that this plugin
 * can rely on, so no counter is invented — the UI says so explicitly instead of
 * showing a number that would be wrong.
 *
 * <p>RuneLite can report the same kill through more than one loot event, so
 * kills are de-duplicated on (npc id, game tick).
 */
@Slf4j
@Singleton
public class KillTrackingService
{
	private final AssignmentService assignmentService;

	private int lastCountedNpcId = -1;
	private int lastCountedTick = -1;

	@Inject
	public KillTrackingService(AssignmentService assignmentService)
	{
		this.assignmentService = assignmentService;
	}

	/**
	 * @param npcId     the NPC that died
	 * @param gameTick  current client tick, used for duplicate suppression
	 * @return true when the kill was counted
	 */
	public boolean onNpcKilled(int npcId, int gameTick)
	{
		final Assignment assignment = assignmentService.getCurrentAssignment();
		if (assignment == null || !assignment.isActive())
		{
			return false;
		}

		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (activity == null || !activity.tracksKills())
		{
			return false;
		}

		if (!activity.getRelevantNpcIds().contains(npcId))
		{
			return false;
		}

		if (npcId == lastCountedNpcId && gameTick == lastCountedTick)
		{
			log.debug("Ignoring duplicate kill event for npc {} on tick {}", npcId, gameTick);
			return false;
		}

		lastCountedNpcId = npcId;
		lastCountedTick = gameTick;

		assignmentService.recordKill();
		return true;
	}

	public void reset()
	{
		lastCountedNpcId = -1;
		lastCountedTick = -1;
	}
}

