package com.collectionlogroulette.service;

import java.util.Collection;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemStack;

/**
 * Converts RuneLite loot events into priced entries on the active assignment.
 *
 * <p>Only loot that RuneLite itself identifies as loot is recorded — NPC drops,
 * PvP drops and the chest/casket style events. Ordinary inventory churn is never
 * inspected, which is why the panel calls the figure an <em>estimate</em> rather
 * than profit: it counts what came in, not what was spent getting it.
 *
 * <h2>Threading</h2>
 * Called from event subscribers on the client thread; {@link ItemResolver}
 * pricing needs that thread anyway.
 */
@Slf4j
@Singleton
public class LootTrackingService
{
	private final AssignmentService assignmentService;
	private final ItemResolver itemResolver;

	@Inject
	public LootTrackingService(AssignmentService assignmentService, ItemResolver itemResolver)
	{
		this.assignmentService = assignmentService;
		this.itemResolver = itemResolver;
	}

	/**
	 * @param items  the loot stacks as reported by RuneLite
	 * @param source human-readable origin, stored on each entry
	 */
	public void recordLoot(Collection<ItemStack> items, String source)
	{
		if (items == null || items.isEmpty())
		{
			return;
		}

		if (assignmentService.getCurrentAssignment() == null
			|| !assignmentService.getCurrentAssignment().isActive())
		{
			return;
		}

		long recorded = 0L;
		for (ItemStack stack : items)
		{
			if (stack == null || stack.getQuantity() <= 0)
			{
				continue;
			}

			// Price is snapshotted now so the running total reflects the value at
			// the time of the drop.
			final int price = itemResolver.getPrice(stack.getId());
			assignmentService.recordLoot(stack.getId(), stack.getQuantity(), price, source);
			recorded += (long) price * stack.getQuantity();
		}

		if (recorded > 0)
		{
			log.debug("Recorded {} gp of loot from {}", recorded, source);
		}
	}
}

package com.collectionlogroulette.service;

import com.collectionlogroulette.model.RouletteActivity;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/**
 * Resolves the item name from a Collection Log announcement to an item id.
 *
 * <p>Resolution is deliberately scoped to the assigned activity first: comparing
 * the announced name against that activity's own item set is exact, whereas a
 * global name search is ambiguous (many items share a display name across
 * variants). Only if that fails does it fall back to a global lookup, and a
 * global lookup that returns anything other than a single unambiguous match is
 * treated as a failure rather than a guess.
 *
 * <h2>Threading</h2>
 * {@link ItemManager#getItemComposition(int)} reads the item cache and must be
 * called on the client thread.
 */
@Slf4j
@Singleton
public class ItemResolver
{
	/** Marker stored in the index when a display name maps to several item ids. */
	private static final int AMBIGUOUS = -2;

	private final ItemManager itemManager;

	/**
	 * Cached display-name index over the catalog. Written on the client thread
	 * and read from it, but volatile so a stale reference cannot be observed if
	 * that ever changes.
	 */
	private volatile Map<String, Integer> catalogNameIndex;

	@Inject
	public ItemResolver(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * Looks for an item with the given display name inside the activity's set.
	 *
	 * @return the matching item id, or {@code -1} if the activity has no item
	 * with that name
	 */
	public int resolveWithinActivity(@Nullable RouletteActivity activity, String itemName)
	{
		if (activity == null || itemName == null)
		{
			return -1;
		}

		final String wanted = normalise(itemName);
		for (int itemId : activity.getCollectionLogItemIds())
		{
			final String name = safeName(itemId);
			if (name != null && normalise(name).equals(wanted))
			{
				return itemId;
			}
		}

		return -1;
	}

	/**
	 * Searches the whole catalog for an activity item matching the name.
	 *
	 * <p>Used so an unlock belonging to a <em>different</em> activity can be
	 * recognised as such and reported as unrelated rather than as unmappable.
	 *
	 * @return the item id, or {@code -1} when there is no match or more than one
	 */
	public int resolveWithinCatalog(ActivityCatalog catalog, String itemName)
	{
		if (itemName == null)
		{
			return -1;
		}

		final Integer found = catalogIndex(catalog).get(normalise(itemName));
		if (found == null)
		{
			return -1;
		}

		if (found == AMBIGUOUS)
		{
			// Two different ids share this display name. Refusing to pick keeps a
			// wrong auto-completion off the table.
			log.debug("Item name '{}' is ambiguous across the catalog; not resolving", itemName);
			return -1;
		}

		return found;
	}

	/**
	 * Lazily built display-name to item-id index over the whole catalog.
	 *
	 * <p>Built once instead of walking every activity's item set and reading a
	 * composition per item on each unlock — that was roughly 500 cache lookups on
	 * the client thread every time an unlock fired.
	 *
	 * <p>Built on first use rather than at construction because item
	 * compositions are only readable once the client has loaded, and this class
	 * is instantiated well before that.
	 */
	private Map<String, Integer> catalogIndex(ActivityCatalog catalog)
	{
		Map<String, Integer> index = catalogNameIndex;
		if (index != null)
		{
			return index;
		}

		index = new HashMap<>();
		for (RouletteActivity activity : catalog.getActivities())
		{
			for (int itemId : activity.getCollectionLogItemIds())
			{
				final String name = safeName(itemId);
				if (name == null || name.isEmpty())
				{
					continue;
				}

				final String key = normalise(name);
				final Integer existing = index.get(key);
				if (existing == null)
				{
					index.put(key, itemId);
				}
				else if (existing != itemId)
				{
					index.put(key, AMBIGUOUS);
				}
			}
		}

		catalogNameIndex = index;
		log.debug("Built catalog item name index with {} entries", index.size());
		return index;
	}

	/**
	 * Discards the cached index. Called when the item cache may have changed
	 * under us, so stale names cannot outlive a client update.
	 */
	public void invalidateCache()
	{
		catalogNameIndex = null;
	}

	/**
	 * GE price for one of the item, or the item's store price when it has no GE
	 * value. Zero for anything that cannot be priced.
	 */
	public int getPrice(int itemId)
	{
		try
		{
			final int gePrice = itemManager.getItemPrice(itemId);
			if (gePrice > 0)
			{
				return gePrice;
			}

			final ItemComposition composition = itemManager.getItemComposition(itemId);
			return composition == null ? 0 : Math.max(0, composition.getPrice());
		}
		catch (RuntimeException e)
		{
			log.debug("Could not price item {}", itemId, e);
			return 0;
		}
	}

	@Nullable
	private String safeName(int itemId)
	{
		try
		{
			final ItemComposition composition = itemManager.getItemComposition(itemId);
			return composition == null ? null : composition.getName();
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read composition for item {}", itemId, e);
			return null;
		}
	}

	private static String normalise(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}
}

