package com.collectionlogroulette.service;

import com.collectionlogroulette.CollectionLogRouletteConfig;
import com.collectionlogroulette.model.RouletteSaveData;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Reads and writes the per-account save blob.
 *
 * <p>Storage goes through {@code ConfigManager}'s RS-profile aware API, so two
 * accounts logged in from the same client never see each other's progress. When
 * no RS profile is active (logged out, or on the login screen) there is nothing
 * safe to write to, and {@link #save} deliberately does nothing rather than
 * risk writing one account's state under another's key.
 *
 * <p>All persistence lives here; event subscribers call into it rather than
 * touching ConfigManager themselves.
 */
@Slf4j
@Singleton
public class PersistenceService
{
	static final String KEY_SAVE_DATA = "saveDataV1";

	private final ConfigManager configManager;
	private final Gson gson;

	/** Suppresses log spam when saving fails repeatedly for the same reason. */
	private boolean warnedAboutMissingProfile;

	@Inject
	public PersistenceService(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * @return true when an RS profile is active and persistence can happen
	 */
	public boolean isProfileAvailable()
	{
		return configManager.getRSProfileKey() != null;
	}

	/**
	 * Loads the current profile's save data.
	 *
	 * <p>Never throws: unparseable, truncated or future-versioned data yields a
	 * fresh {@link RouletteSaveData} instead. Losing roulette progress is a bad
	 * day; taking the client down with a JSON error is worse.
	 */
	public RouletteSaveData load()
	{
		final String json = configManager.getRSProfileConfiguration(
			CollectionLogRouletteConfig.GROUP, KEY_SAVE_DATA);

		if (json == null || json.trim().isEmpty())
		{
			return new RouletteSaveData();
		}

		final RouletteSaveData parsed = parse(json);
		if (parsed == null)
		{
			return new RouletteSaveData();
		}

		if (parsed.getSchemaVersion() > RouletteSaveData.CURRENT_SCHEMA_VERSION)
		{
			log.warn("Collection Log Roulette save data is version {} but this build understands {}; "
					+ "starting fresh to avoid misreading it",
				parsed.getSchemaVersion(), RouletteSaveData.CURRENT_SCHEMA_VERSION);
			return new RouletteSaveData();
		}

		return parsed;
	}

	@Nullable
	private RouletteSaveData parse(String json)
	{
		try
		{
			final RouletteSaveData data = gson.fromJson(json, RouletteSaveData.class);
			if (data == null)
			{
				log.warn("Collection Log Roulette save data was empty JSON; starting fresh");
			}
			return data;
		}
		catch (JsonParseException e)
		{
			log.warn("Collection Log Roulette save data could not be parsed; starting fresh", e);
			return null;
		}
		catch (RuntimeException e)
		{
			// Gson can surface enum/number coercion failures as plain runtime
			// exceptions; treat any of them as corrupt data.
			log.warn("Collection Log Roulette save data was rejected; starting fresh", e);
			return null;
		}
	}

	public void save(RouletteSaveData data)
	{
		if (data == null)
		{
			return;
		}

		if (!isProfileAvailable())
		{
			if (!warnedAboutMissingProfile)
			{
				log.debug("No RuneScape profile active; skipping save until an account is logged in");
				warnedAboutMissingProfile = true;
			}
			return;
		}

		warnedAboutMissingProfile = false;
		data.setSchemaVersion(RouletteSaveData.CURRENT_SCHEMA_VERSION);

		try
		{
			configManager.setRSProfileConfiguration(
				CollectionLogRouletteConfig.GROUP, KEY_SAVE_DATA, gson.toJson(data));
		}
		catch (RuntimeException e)
		{
			log.warn("Failed to persist Collection Log Roulette progress", e);
		}
	}
}

