package com.collectionlogroulette.service;

import com.collectionlogroulette.model.CollectionLogUnlock;
import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;

/**
 * Parses the game's "new collection log item" announcement.
 *
 * <p>The game can deliver this two ways, controlled by the in-game setting
 * behind {@code VarbitID.OPTION_COLLECTION_NEW_ITEM}: as a chat message, as a
 * pop-up notification, or as both. Both paths funnel through here, and the
 * duplicate window below is what stops the "both" setting from firing twice.
 */
@Slf4j
@Singleton
public class ChatCollectionLogDetectionService implements CollectionLogDetectionService
{
	/**
	 * The official chat announcement. Anchored at the start so an ordinary player
	 * message quoting the phrase cannot trigger it, and tolerant of the trailing
	 * punctuation and tags the game adds.
	 */
	private static final Pattern CHAT_PATTERN = Pattern.compile(
		"^New item added to your collection log:\\s*(.+?)\\s*$", Pattern.CASE_INSENSITIVE);

	/** Title used by the pop-up variant of the same announcement. */
	private static final String NOTIFICATION_TITLE = "collection log";

	/**
	 * The game emits U+00A0 in places. Left in the string it becomes part of the
	 * item name and the item lookup then silently fails, so it is folded to an
	 * ordinary space up front. Declared as an escape rather than typed inline so
	 * the source survives editors that would mangle a literal.
	 */
	private static final char NON_BREAKING_SPACE = ' ';

	/**
	 * Chat and pop-up arrive within a tick or two of each other. Anything inside
	 * this window naming the same item is treated as the same unlock.
	 */
	static final long DUPLICATE_WINDOW_MILLIS = 5_000L;

	@Nullable
	private String lastItemName;
	private long lastTimestampMillis;

	@Override
	public Optional<CollectionLogUnlock> detectUnlock(String rawText, long timestampMillis)
	{
		if (rawText == null)
		{
			return Optional.empty();
		}

		final String cleaned = clean(rawText);
		if (cleaned.isEmpty())
		{
			return Optional.empty();
		}

		final Matcher matcher = CHAT_PATTERN.matcher(cleaned);
		if (!matcher.matches())
		{
			return Optional.empty();
		}

		return accept(normaliseItemName(matcher.group(1)), timestampMillis);
	}

	@Override
	public Optional<CollectionLogUnlock> detectUnlockFromNotification(String title, String body, long timestampMillis)
	{
		if (title == null || body == null)
		{
			return Optional.empty();
		}

		final String cleanTitle = clean(title);
		if (!cleanTitle.toLowerCase(Locale.ROOT).startsWith(NOTIFICATION_TITLE))
		{
			return Optional.empty();
		}

		final String itemName = normaliseItemName(clean(body));
		if (itemName.isEmpty())
		{
			return Optional.empty();
		}

		return accept(itemName, timestampMillis);
	}

	@Override
	public void reset()
	{
		lastItemName = null;
		lastTimestampMillis = 0L;
	}

	private Optional<CollectionLogUnlock> accept(String itemName, long timestampMillis)
	{
		if (itemName.isEmpty())
		{
			return Optional.empty();
		}

		if (isDuplicate(itemName, timestampMillis))
		{
			log.debug("Ignoring duplicate collection log notification for '{}'", itemName);
			return Optional.empty();
		}

		lastItemName = itemName;
		lastTimestampMillis = timestampMillis;

		return Optional.of(new CollectionLogUnlock(itemName, timestampMillis));
	}

	private boolean isDuplicate(String itemName, long timestampMillis)
	{
		if (lastItemName == null || !lastItemName.equalsIgnoreCase(itemName))
		{
			return false;
		}

		final long delta = timestampMillis - lastTimestampMillis;
		return delta >= 0 && delta < DUPLICATE_WINDOW_MILLIS;
	}

	/** Strips Jagex tags and normalises whitespace before any matching happens. */
	private static String clean(String raw)
	{
		return Text.removeTags(raw).replace(NON_BREAKING_SPACE, ' ').trim();
	}

	/**
	 * The chat line ends in a full stop and the pop-up sometimes wraps the name in
	 * quotes; neither is part of the item name.
	 */
	private static String normaliseItemName(String raw)
	{
		String name = raw.trim();

		while (name.endsWith(".") || name.endsWith("!"))
		{
			name = name.substring(0, name.length() - 1).trim();
		}

		if (name.length() > 1
			&& (name.startsWith("\"") && name.endsWith("\"") || name.startsWith("'") && name.endsWith("'")))
		{
			name = name.substring(1, name.length() - 1).trim();
		}

		return name;
	}
}

