package com.collectionlogroulette.service;

import com.collectionlogroulette.model.RouletteActivity;
import com.collectionlogroulette.model.WeightCategory;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Picks the next activity from a pre-filtered pool of eligible activities.
 *
 * <p>Deliberately knows nothing about config objects, the client or the panel:
 * it takes a list, a mode and a weight map, and returns a choice. The {@link
 * Random} is constructor-injected so tests can drive it with a fixed seed.
 */
@Slf4j
@Singleton
public class AssignmentSelectionService
{
	private final Random random;

	@Inject
	public AssignmentSelectionService()
	{
		this(new Random());
	}

	public AssignmentSelectionService(Random random)
	{
		this.random = random;
	}

	/**
	 * @param eligible           activities that passed every eligibility filter
	 * @param previousActivityId activity to avoid repeating, may be null
	 * @param mode               pure or weighted
	 * @param weights            weight per category; ignored in pure mode
	 * @param avoidRepeat        whether to honour {@code previousActivityId}
	 * @return the chosen activity, or empty when {@code eligible} is empty
	 */
	public Optional<RouletteActivity> select(
		List<RouletteActivity> eligible,
		@Nullable String previousActivityId,
		SelectionMode mode,
		Map<WeightCategory, Integer> weights,
		boolean avoidRepeat)
	{
		if (eligible == null || eligible.isEmpty())
		{
			return Optional.empty();
		}

		final List<RouletteActivity> pool = applyRepeatAvoidance(eligible, previousActivityId, avoidRepeat);

		final RouletteActivity chosen = mode == SelectionMode.WEIGHTED
			? selectWeighted(pool, weights)
			: pool.get(random.nextInt(pool.size()));

		return Optional.ofNullable(chosen);
	}

	/**
	 * Drops the previous activity from the pool, but only when something else is
	 * left — with a single eligible activity, repeating it beats rolling nothing.
	 */
	private static List<RouletteActivity> applyRepeatAvoidance(
		List<RouletteActivity> eligible, @Nullable String previousActivityId, boolean avoidRepeat)
	{
		if (!avoidRepeat || previousActivityId == null || eligible.size() < 2)
		{
			return eligible;
		}

		final List<RouletteActivity> filtered = new ArrayList<>(eligible.size());
		for (RouletteActivity activity : eligible)
		{
			if (!previousActivityId.equals(activity.getId()))
			{
				filtered.add(activity);
			}
		}

		return filtered.isEmpty() ? eligible : filtered;
	}

	/**
	 * Two-stage draw: pick a category proportionally to its weight, then pick
	 * uniformly inside it. Categories with no eligible activities are excluded
	 * before normalising, so their weight is redistributed rather than wasted.
	 */
	@Nullable
	private RouletteActivity selectWeighted(List<RouletteActivity> pool, Map<WeightCategory, Integer> weights)
	{
		final Map<WeightCategory, List<RouletteActivity>> buckets = new EnumMap<>(WeightCategory.class);
		for (RouletteActivity activity : pool)
		{
			buckets.computeIfAbsent(activity.getType().getWeightCategory(), k -> new ArrayList<>()).add(activity);
		}

		int totalWeight = 0;
		for (Map.Entry<WeightCategory, List<RouletteActivity>> entry : buckets.entrySet())
		{
			totalWeight += weightFor(weights, entry.getKey());
		}

		if (totalWeight <= 0)
		{
			// Every populated category was weighted to zero. Falling back to a flat
			// draw is better than refusing to roll.
			log.debug("All eligible categories have zero weight; falling back to uniform selection");
			return pool.get(random.nextInt(pool.size()));
		}

		int roll = random.nextInt(totalWeight);
		for (Map.Entry<WeightCategory, List<RouletteActivity>> entry : buckets.entrySet())
		{
			roll -= weightFor(weights, entry.getKey());
			if (roll < 0)
			{
				final List<RouletteActivity> bucket = entry.getValue();
				return bucket.get(random.nextInt(bucket.size()));
			}
		}

		// Unreachable while totalWeight is the sum of the same weights, but a
		// defined fallback beats returning null.
		return pool.get(pool.size() - 1);
	}

	private static int weightFor(Map<WeightCategory, Integer> weights, WeightCategory category)
	{
		final Integer weight = weights.get(category);
		return weight == null ? 0 : Math.max(0, weight);
	}
}

package com.collectionlogroulette;

import com.collectionlogroulette.model.Assignment;
import com.collectionlogroulette.model.AssignmentState;
import com.collectionlogroulette.model.RouletteActivity;
import com.collectionlogroulette.service.AssignmentService;
import com.collectionlogroulette.ui.UiUtils;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.api.MenuAction;

/**
 * Small in-game summary of the current assignment.
 *
 * <p>Render work is kept to string formatting over already-computed state; the
 * overlay never reads the client or recomputes eligibility, because this runs
 * every frame.
 */
public class CollectionLogRouletteOverlay extends OverlayPanel
{
	private final AssignmentService assignmentService;
	private final CollectionLogRouletteConfig config;

	@Inject
	CollectionLogRouletteOverlay(CollectionLogRoulettePlugin plugin,
		AssignmentService assignmentService, CollectionLogRouletteConfig config)
	{
		super(plugin);
		this.assignmentService = assignmentService;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", "Collection Log Roulette overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		final Assignment assignment = assignmentService.getCurrentAssignment();
		final RouletteActivity activity = assignmentService.getCurrentActivity();
		if (assignment == null || activity == null || assignment.getState() == AssignmentState.NONE)
		{
			return null;
		}

		final boolean completed = assignment.getState() == AssignmentState.COMPLETED;

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Collection Log Roulette")
			.color(completed ? UiUtils.SUCCESS : Color.WHITE)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Assignment:")
			.right(activity.getDisplayName())
			.build());

		if (config.compactOverlay())
		{
			// Compact mode keeps the clock, since that is the field people watch.
			if (config.overlayShowTime())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Time:")
					.right(UiUtils.formatDuration(elapsed(assignment, completed)))
					.build());
			}

			panelComponent.setPreferredSize(new Dimension(160, 0));
			return super.render(graphics);
		}

		if (config.overlayShowTime())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Time:")
				.right(UiUtils.formatDuration(elapsed(assignment, completed)))
				.build());
		}

		if (config.overlayShowLoot())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Loot:")
				.right(UiUtils.formatGp(assignment.getTotalLootValue()))
				.build());
		}

		if (config.overlayShowKills() && activity.tracksKills())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Kills:")
				.right(Integer.toString(assignment.getKillCount()))
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Status:")
			.right(describeStatus(assignment, completed))
			.rightColor(statusColor(assignment, completed))
			.build());

		panelComponent.setPreferredSize(new Dimension(160, 0));
		return super.render(graphics);
	}

	private long elapsed(Assignment assignment, boolean completed)
	{
		// Once completed the clock is frozen at whatever was banked.
		return completed ? assignment.getAccumulatedMillis() : assignmentService.getElapsedMillis();
	}

	private static String describeStatus(Assignment assignment, boolean completed)
	{
		if (completed)
		{
			return "Complete";
		}

		return assignment.isTimerRunning() ? "Active" : "Paused";
	}

	private static Color statusColor(Assignment assignment, boolean completed)
	{
		if (completed)
		{
			return UiUtils.SUCCESS;
		}

		return assignment.isTimerRunning() ? Color.WHITE : UiUtils.WARNING;
	}
}
